# out of a tensor in one form of its operands only (a 0-dim tensor where a
# number is declared): the member, the form that reads and its construct,
# a form that does not and its construct. The member's call is on line 10.
TORCH_READ_FORMS = {
    "masked_fill": (
        "torch.Tensor.masked_fill",
        ("0:T 1:T 2:T", "r = y.masked_fill(y > 0.5, x[0, 0])"),
        ("0:T 1:T", "r = y.masked_fill(y > 0.5, 2.0)"),
    ),
    "foreach_add": (
        "torch._foreach_add",
        ("0:[T] 1:T", "r = torch._foreach_add([y, y], x[0, 0])[1]"),
        ("0:[T] 1:[T]", "r = torch._foreach_add([y, y], [x, x])[1]"),
    ),
    "foreach_add_": (
        "torch._foreach_add_",
        ("0:[T] 1:T -:K", "torch._foreach_add_([y], x[0, 0])\nr = y * 1.0"),
        ("0:[T]", "torch._foreach_add_([y], 2.0)\nr = y * 1.0"),
    ),
    "foreach_maximum_": (
        "torch._foreach_maximum_",
        ("0:[T] 1:T", "torch._foreach_maximum_([y], x[0, 0])\nr = y * 1.0"),
        ("0:[T] 1:[T]", "torch._foreach_maximum_([y], [x])\nr = y * 1.0"),
    ),
    "linspace": (
        "torch.linspace",
        ("0:T 1:T", "r = torch.linspace(x[0, 0], x[0, 1], 5)"),
        ("plain", "r = torch.linspace(0.0, 1.0, 5)"),
    ),
    "tensor": (
        "torch.tensor",
        ("0:[T]", "r = torch.tensor([x[0, 0], x[0, 1]])"),
        ("plain", "r = torch.tensor([1.0, 2.0])"),
    ),
    "quantize_per_tensor": (
        "torch.quantize_per_tensor",
        (
            "0:T 1:T 2:T",
            "r = torch.quantize_per_tensor(y, x[0, 0].abs() + 0.1, (x[0, 0] * 0).long(), torch.quint8).dequantize()",
        ),
        ("0:T", "r = torch.quantize_per_tensor(y, 0.1, 0, torch.quint8).dequantize()"),
    ),
}
# Those of them whose row no region runs over: the result is a quantized
# tensor, which the tracer of a region does not hold (the trace is given up).
TORCH_READ_FORMS_UNTRACED = {"quantize_per_tensor"}
# A program per set of KEYWORDS of a form of a C callee of torch that has a
# line per set (the calls with one set read a value out of a tensor, those
# with another do not: the parser takes another overload): the member, the
# form without its keywords, the keywords the call passes, what the rules
# say of the line of exactly those, and the construct; (None, None): a call
# whose keywords come in a dict, which no line tells. The member's call is
# on line 10.
TORCH_KEYWORD_FORMS = {
    "foreach_add_no_keyword": (
        "torch._foreach_add_",
        "0:[T] 1:T",
        (),
        "stop",
        "torch._foreach_add_([y], x[0, 0])\nr = y * 1.0",
    ),
    "foreach_add_alpha": (
        "torch._foreach_add_",
        "0:[T] 1:T",
        ("alpha",),
        "row",
        "torch._foreach_add_([y], x[0, 0], alpha=0.5)\nr = y * 1.0",
    ),
    "foreach_add_star": (
        "torch._foreach_add_",
        "0:[T] 1:T",
        None,
        None,
        "torch._foreach_add_([y], x[0, 0], **{'alpha': 0.5})\nr = y * 1.0",
    ),
}
TORCH_NO_ROW = {
    "out": ("torch.add", "r = torch.zeros_like(y)\ntorch.add(y, 1.0, out=r)"),
    "partial": ("torch.add", "r = functools.partial(torch.add, y)(1.0)"),
    "numpy_operand": ("torch.add", "r = torch.add(y, numpy.float32(1.0))"),
}


def torch_key_of_the_write(written, rekeyed):
    """Whether the measured column K names no change of a key, or only what
    autograd makes of an in-place write that the column W names: the written
    operand comes to require grad when another operand does."""
    wrote = {w.partition("(")[0] for w in written.rpartition("@")[0].split(",")}
    changes = rekeyed.rpartition("@")[0]
    return changes == "no" or all(
        one.partition("(")[0] in wrote
        and set(one.partition("(")[2].partition(")")[0].split())
        <= {"leaf", "requires_grad"}
        for one in changes.split(",")
    )


def torch_source(construct):
    body = "\n".join(f"    {line}" for line in construct.splitlines())
    return (
        "import functools\nimport numpy\nimport torch\n"
        "import torch.nn.functional as F\nfrom torch.nn.utils import rnn\n"
        "torch.manual_seed(0)\n"
        # (One line: the tests know the construct's line.)
        "LSTM, GRU, RNN_TANH = torch.nn.LSTM(2, 3), torch.nn.GRU(2, 3), torch.nn.RNN(2, 3); "
        "RNN_RELU = torch.nn.RNN(2, 3, nonlinearity='relu')\n"
        f"def f(x):\n    y = torch.sin(x) * 2.0 + torch.cos(x)\n{body}\n"
        "    return torch.tanh(y).sum() + (r * 2.0).sum(), r\n"
    )


# A body with a member that has a row (gelu, a builtin bound to its module),
# run 8 times under vm in a process of its own, after one thing is made
# other about the table's names (sys.argv[1]): prints whether every call
# gave eager's values, how often a region over f ran, and why traces were
# refused or places had no region.
TORCH_TABLE_PROGRAM = """
import json, sys, types, torch, torch.nn.functional as F
from torch import vm

class Other(types.ModuleType):
    pass

if sys.argv[1] == "a_name_resolves_to_nothing":
    del torch._C._nn.hardtanh_
elif sys.argv[1] == "a_module_of_another_class":
    torch._C._nn.__class__ = Other

def f(x):
    y = torch.sin(x) * 2.0 + torch.cos(x)
    r = F.gelu(y)
    return torch.tanh(y).sum() + (r * 2.0).sum(), r

compiled = vm(f, passes=vm.configure(vm.DEFAULT_PASSES, regions={"at": 3, "observe": 1}, pure_calls=1))
same = []
for call in range(8):
    x = torch.randn(6, 8, generator=torch.Generator().manual_seed(call))
    got, want = compiled(x), f(x)
    same.append(all(bool((a == b).all()) for a, b in zip(got, want, strict=True)))
rows = [r for r in vm.regions(compiled) if r["function"] == "f"]
runs = sum(r["runs"] for r in rows if r["state"] == "region")
whys = {str(why) for r in rows for _, why in r.get("traces", ()) if why}
whys |= {str(r["why"]) for r in rows if r.get("why")}
print(json.dumps({"same": same, "runs": runs, "whys": sorted(whys)}))
"""


@instantiate_parametrized_tests
@unittest.skipUnless(CHECKS_HAS_VM, "needs the torch._rust extension and CPython 3.12")
class TestVmRulesTorch(TestCase):
    """A C callee of torch has a row only if calls of it were measured, on
    the CPU and on CUDA, to enter no Python code, change no operand, draw
    nothing, repeat bit for bit and give results whose count and sizes do not
    follow data; the row is for plain operands and no ``out=``. A callee
    measured to do otherwise stops a trace wherever it is called, and one
    that draws or returns a fact is left to the code that decided before
    (one that writes: TestVmRulesTorchWrites). A callee that only the sizes of its results stand against, and
    that was measured apart for each form of its operands, has a row for the
    forms whose own samples are clean; a call of it in any other form stops
    the trace. A callee under whose calls a value was read out of a tensor
    (what the engine's witness saw under one call per sample), or no call of
    which was witnessed, has no row: its result, or whether it raises,
    follows the value; one that reads in some forms of its operands only
    has a row for the forms whose calls read none. The table is a file of
    measured verdicts; every name in it is the object the measurement
    called."""

    hw_classification = HardwareClassification.GENERIC
    COLUMNS = [
        "member",
        "form",
        "kind",
        "cpu",
        "cuda",
        "scpu",
        "scuda",
        "out",
        "P",
        "W",
        "K",
        "D",
        "S",
        "R",
        "A",
        "L",
        "O",
        "X",
        "domain",
    ]
    KINDS = {
        "builtin": "builtin_function_or_method",
        "method_descriptor": "method_descriptor",
        "wrapper_descriptor": "wrapper_descriptor",
        "classmethod_descriptor": "classmethod_descriptor",
        "slot": "getset_descriptor",
    }

    def lines(self, forms=False):
        """The lines of the members, or those of their forms."""
        path = os.path.join(CRATE, "exec", "rules", "torch_members.tsv")
        if not os.path.exists(path):
            self.skipTest("the executor's source is not beside the tests")
        with open(path) as f:
            rows = [line.rstrip("\n").split("\t") for line in f if line[0] != "#"]
        self.assertEqual(rows[0], self.COLUMNS)
        found = [dict(zip(self.COLUMNS, row, strict=True)) for row in rows[1:]]
        return [line for line in found if (line["form"] != "-") == forms]

    def member(self, name):
        """The object a member's name says, found as the measurement finds
        it: the C member of the class of tensors, else the attributes from
        the longest importable module on."""
        parts = name.removesuffix(".__get__").split(".")
        own = vars(torch._C.TensorBase)
        if parts[:2] == ["torch", "Tensor"] and len(parts) == 3 and parts[2] in own:
            return own[parts[2]]
        for at in range(len(parts), 0, -1):
            try:
                found = importlib.import_module(".".join(parts[:at]))
            except ImportError:
                continue
            return functools.reduce(getattr, parts[at:], found)
        self.fail(f"{name} resolves to nothing")

    def only_reads(self, line):
        """Whether a member's line says of every call measured that it only
        computes, and of some that a value was read out of a tensor under it
        (X): nothing else stands against the member."""

        def said(column):
            return line[column].rpartition("@")[0]

        return (
            said("X").startswith("yes(")
            and [said(c) for c in "WKDSR"] == ["no"] * 3 + ["key", "yes"]
            and said("P").partition("(")[0] in ("no", "warn")
            and all(int(line[c]) >= 5 for c in ("cpu", "cuda", "scpu", "scuda"))
            and line["O"].startswith("nested=key")
            and "no-tensor-result" not in line["A"]
            and ("follows=" not in line["L"] or "follows=none" in line["L"])
            and "pyval=data" not in line["L"]
        )

    def test_the_file_parses_and_every_member_resolves(self):
        lines = self.lines()
        table = {name: (at, status) for name, at, status in torch._rust._rules_torch()}
        self.assertEqual(sorted(table), sorted(line["member"] for line in lines))
        self.assertEqual(len(table), len(lines))
        self.assertGreater(len(lines), 250)
        for line in lines:
            with self.subTest(member=line["member"]):
                found = self.member(line["member"])
                self.assertEqual(type(found).__name__, self.KINDS[line["kind"]])
                self.assertEqual(table[line["member"]][0], id(found))

    def test_a_row_is_a_member_measured_to_only_compute(self):
        table = {name: status for name, _, status in torch._rust._rules_torch()}
        dumped = collections.Counter()
        for line in torch._rust._rules_dump().splitlines():
            how, family, what, *rest = line.split("\t")
            if family == "torch":
                # (A row for one form of a call: `CALLEE (FORM)`.)
                member, _, form = what.partition(" (")
                dumped[member] += 1
                self.assertEqual(table[member].partition(":")[0], how)
                if how == "row" and rest[2] == "None" and not form:
                    self.assertEqual(rest[3], "Entry")
        self.assertEqual(len(dumped), len(table))

        def said(line, column):
            return line[column].rpartition("@")[0]

        # The members that are rows by a form of their operands.
        forms = torch._rust._rules_torch_forms()
        rows = {member for member, _, status in forms if status == "row"}
        left = {member: status for member, _, status in forms if ":" in status}

        for line in self.lines():
            with self.subTest(member=line["member"]):
                status = table[line["member"]]
                # (A member with lines per form: its forms are tested below.)
                formed = any(member == line["member"] for member, _, _ in forms)
                quiet = all(said(line, c) == "no" for c in "WKD")
                sized = said(line, "S").startswith("data")
                python = said(line, "P").startswith("yes")
                differs = said(line, "R").startswith("NO")
                # It writes or re-keys an operand and draws nothing: a row
                # of its own only if a schema declares every write measured
                # and no key was changed; else by its forms (tested apart).
                writer = not quiet and said(line, "D") == "no" and not sized
                writer = writer and not python
                if status == "row" and not formed and writer:
                    for write in said(line, "W").split(","):
                        self.assertEqual(write.partition("(")[2][:5], "decl;")
                    self.assertTrue(torch_key_of_the_write(line["W"], line["K"]))
                elif status == "row" and not formed:
                    self.assertTrue(quiet)
                if writer:
                    self.assertIn(status, ("row", "stop"))
                # It draws from a random generator and nothing else stands
                # against it: by its forms (in which form it draws), with
                # lines of forms; left as it was with none.
                drawer = said(line, "D") != "no" and not sized and not python
                drawer = drawer and (said(line, "S"), said(line, "R")) == ("key", "yes")
                drawer = drawer and "nested=data" not in line["O"]
                if drawer:
                    self.assertIn(
                        status, ("row", "stop") if formed else ("later:ambient",)
                    )
                if status == "row" and not formed:
                    self.assertIn(said(line, "P").partition("(")[0], ("no", "warn"))
                    self.assertEqual((said(line, "S"), said(line, "R")), ("key", "yes"))
                    # Enough samples returned, and enough of them had their
                    # results compared on other data, on each device.
                    for count in ("cpu", "cuda", "scpu", "scuda"):
                        self.assertGreaterEqual(int(line[count]), 5)
                    self.assertNotIn("no-tensor-result", line["A"])
                    self.assertTrue(line["O"].startswith("nested=key"))
                    self.assertNotEqual(line["domain"], "-")
                    # No call witnessed read a value out of a tensor.
                    self.assertEqual(said(line, "X"), "no")
                # A value was read under some call, or none was witnessed:
                # no row but by a form of its own samples.
                if said(line, "X") != "no" and not formed:
                    self.assertNotEqual(status, "row")
                # The operators under the call differ with the data.
                if "nested=data" in line["O"]:
                    self.assertEqual(status, "stop")
                if sized or (differs and quiet and not python):
                    member = line["member"]
                    want = "row" if member in rows else left.get(member, "stop")
                    self.assertEqual(status, want)
                # (By its forms: a writer, one that only its results
                # following data, and draws, stand against, or one that only
                # a value read under some calls stands against.)
                still = all(said(line, c) == "no" for c in "WK")
                by_forms = writer or drawer or (sized and still and not python)
                self.assertLessEqual(formed, by_forms or self.only_reads(line))
                self.assertLessEqual(self.only_reads(line), formed)
                # Python under the call: neither a row nor yet a stop.
                self.assertEqual(python and not sized, status == "later:native")
                if status.startswith("later:"):
                    self.assertEqual(sized, line["member"] in left)
                    self.assertIn(status.partition(":")[2], RULES_LATER)

    def test_a_form_is_a_row_only_on_samples_of_its_own(self):
        forms = {
            (m, form): status for m, form, status in torch._rust._rules_torch_forms()
        }
        members = {name: status for name, _, status in torch._rust._rules_torch()}
        # The lines of the forms of a member that goes by its own line (a
        # writer whose every write a schema declares) say no more than it.
        by_form = {member for member, _ in forms}
        whole = {x["member"] for x in self.lines(forms=True)} - by_form
        self.assertEqual({members[member] for member in whole}, {"row"})
        writers = {
            x["member"]
            for x in self.lines()
            if any(x[c].rpartition("@")[0] != "no" for c in "WK")
            and "nested=data" not in x["O"]
        }
        self.assertLessEqual(whole, writers)
        # The members that only a value read under some calls stands against.
        readers = {x["member"] for x in self.lines() if self.only_reads(x)}
        self.assertEqual(readers & writers, set())
        # The members that draw from a random generator and go by forms.
        drawers = {
            x["member"]
            for x in self.lines()
            if x["D"].rpartition("@")[0] != "no"
            and x["S"].rpartition("@")[0] == "key"
            and x["member"] in by_form
        }
        self.assertEqual(readers & drawers, set())
        lines = [x for x in self.lines(forms=True) if x["member"] in by_form]
        self.assertEqual(sorted(forms), sorted((x["member"], x["form"]) for x in lines))
        rows, later = collections.Counter(), {}
        for line in lines:
            with self.subTest(member=line["member"], form=line["form"]):
                status = forms[line["member"], line["form"]]
                clean = [line[c].rpartition("@")[0] for c in "PWKDSR"]
                enough = all(
                    int(line[d]) >= 5 for d in ("cpu", "cuda", "scpu", "scuda")
                ) and line["O"].startswith("nested=key")
                # No call of this form that was witnessed read a value.
                unread = line["X"].rpartition("@")[0] == "no"
                if line["member"] in writers | drawers:
                    # The form of a writer, or of a member that draws: what
                    # it writes, and whether it draws, is the row's.
                    del clean[1]
                    if line["member"] in drawers:
                        clean[2] = "no"
                    is_row = clean == ["no"] * 3 + ["key", "yes"] and enough
                    is_row = is_row and unread
                    self.assertEqual(status, "row" if is_row else "stop")
                elif line["member"] in readers:
                    # The member's line says the rest of every form; the
                    # form's own says whether its calls read, on its samples.
                    # A row needs every sample of the form witnessed.
                    counts = [int(line[d]) for d in ("cpu", "cuda")]
                    is_row = unread and min(counts) >= 5
                    is_row = is_row and int(line["X"].rpartition("@")[2]) == sum(counts)
                    self.assertEqual(status, "row" if is_row else "stop")
                else:
                    is_row = clean == ["no"] * 4 + ["key", "yes"] and enough
                    is_row = is_row and "no-tensor-result" not in line["A"]
                    is_row = is_row and unread
                    self.assertEqual(status == "row", is_row)
                    # Left to another family: calls that hand no tensor,
                    # with nothing against them but that nothing was compared.
                    if status.startswith("later:"):
                        self.assertEqual(line["form"], "plain")
                        self.assertNotIn("data", line["S"])
                        self.assertIn(status.partition(":")[2], RULES_LATER)
                        later[line["member"]] = status
                self.assertNotIn("?", line["form"] if is_row else "")
                self.assertRegex(
                    line["form"],
                    r"^(\?|plain|-:K|\w+:(T|\[T\]|True|False|K)( \w+:(T|\[T\]|True|False|K))*( -:K)?)$",
                )
                rows[line["member"]] += is_row
        # A member is a row exactly if a form of it is; with no such form it
        # is left, whole, to the family a form of it is left to.
        for member, count in rows.items():
            want = "row" if count else later.get(member, "stop")
            self.assertEqual(members[member], want, msg=member)
        self.assertEqual(
            {m for m, _ in TORCH_FORM_ROWS.values()},
            {m for m in rows if rows[m] and m not in writers | readers | drawers},
        )
        # A member under whose calls a value is read in some form, and that
        # has a row for another: a program for the form that reads and one
        # for a form that does not.
        reads = {
            x["member"]
            for x in self.lines()
            if x["X"].startswith("yes(") and x["member"] in writers | readers
        }
        self.assertEqual(
            {member for member, _, _ in TORCH_READ_FORMS.values()},
            {m for m in reads if rows[m]},
        )
        # One that reads in every form stops whole, and has a program too.
        whole = {m for m in reads if not rows[m]}
        self.assertLessEqual(whole, {member for member, _ in TORCH_READS.values()})
        self.assertEqual({members[m] for m in whole}, {"stop"})

    def test_every_data_sized_member_has_a_program(self):
        sized = {
            line.split("\t")[2]
            for line in torch._rust._rules_dump().splitlines()
            if line.startswith("stop\ttorch\t") and "follow the data" in line
        }
        covered = {member for members, _ in TORCH_SIZED.values() for member in members}
        self.assertEqual(sized - covered, set())
        self.assertGreater(len(sized), 15)

    def calls(self, construct, device="cpu"):
        """13 calls of the program beside eager, the data other on every
        second call with the same shapes. Returns the compiled function."""
        os.environ["TORCH_RUST_GATE_HIST"] = "1"
        space = {}
        exec(compile(torch_source(construct), "<torch member>", "exec"), space)
        compiled = vm(space["f"], passes=CHECKS_EARLY)
        for call in range(13):
            torch.manual_seed(call // 2)
            x = torch.randn(6, 8, device=device)
            want = checks_outcome(space["f"], x)
            got = checks_outcome(compiled, x)
            self.assertEqual(type(got), type(want), msg=f"call {call}: {got!r}")
            if isinstance(want, Exception):
                self.assertEqual(str(got), str(want), msg=f"call {call}")
                continue
            for a, b in zip(got, want, strict=True):
                self.assertEqual(a.shape, b.shape, msg=f"call {call}")
                self.assertEqual(a, b, atol=0, rtol=0, msg=f"call {call}")
        return compiled

    def met_and_refused(self, compiled, member):
        """How many traces came to a call of the member, and how many were
        refused for it by the rules."""
        owner, _, name = member.rpartition(".")
        owner = {
            "torch.Tensor": "torch._C.TensorBase",
            "torch": "torch._C._VariableFunctionsClass",
            "torch._C._VariableFunctions": "torch._C._VariableFunctionsClass",
        }.get(owner, owner)
        rows = torch._rust._gate_report()["rows"]
        met = sum(r[3] for r in rows if r[1] == f"call c {owner}.{name}")
        whys = [str(w) for p in vm.regions(compiled) for _, w in p.get("traces", ())]
        return met, sum(f"no row for: {member} " in why for why in whys)

    @parametrize("name", list(TORCH_SIZED))
    @checks_isolated
    def test_a_data_sized_member_is_in_no_region(self, name):
        members, construct = TORCH_SIZED[name]
        compiled = self.calls(construct)
        for member in members:
            met, refused = self.met_and_refused(compiled, member)
            self.assertEqual(met, refused, msg=f"{member}: {vm.regions(compiled)}")

    @parametrize("member", list(TORCH_ROWS))
    @checks_isolated
    def test_a_region_runs_over_a_row(self, member):
        table = {name: status for name, _, status in torch._rust._rules_torch()}
        self.assertEqual(table[member], "row")
        compiled = self.calls(TORCH_ROWS[member])
        met, refused = self.met_and_refused(compiled, member)
        self.assertGreater(met, 0)
        self.assertEqual(refused, 0)
        # The member's line is 10: a region that begins before it and ends
        # behind it ran.
        runs = sum(
            r["runs"]
            for r in vm.regions(compiled)
            if r["function"] == "f"
            and r["state"] == "region"
            and r["lines"][0] < 10 < r["lines"][1]
        )
        self.assertGreater(runs, 0, msg=str(vm.regions(compiled)))

    @parametrize("name", list(TORCH_FORM_ROWS))
    @checks_isolated
    def test_a_region_runs_over_a_form_that_is_a_row(self, name):
        member, construct = TORCH_FORM_ROWS[name]
        # Every call here hands one tensor, its first operand.
        self.assertIn((member, "0:T", "row"), torch._rust._rules_torch_forms())
        compiled = self.calls(construct)
        met, refused = self.met_and_refused(compiled, member)
        self.assertGreater(met, 0)
        self.assertEqual(refused, 0, msg=str(vm.regions(compiled)))
        if name == "topk":
            # (Its result is a structseq, which no block is over yet.)
            return
        # As for a row: the call is on line 10.
        runs = sum(
            r["runs"]
            for r in vm.regions(compiled)
            if r["function"] == "f"
            and r["state"] == "region"
            and r["lines"][0] < 10 < r["lines"][1]
        )
        self.assertGreater(runs, 0, msg=str(vm.regions(compiled)))

    @parametrize("name", list(TORCH_FORM_STOPS))
    @checks_isolated
    def test_a_form_that_is_no_row_is_in_no_region(self, name):
        member, form, construct = TORCH_FORM_STOPS[name]
        self.assertIn((member, form, "stop"), torch._rust._rules_torch_forms())
        compiled = self.calls(construct)
        met, refused = self.met_and_refused(compiled, member)
        if name in TORCH_FORM_STOPS_ALONE:
            self.assertGreater(refused, 0, msg=str(vm.regions(compiled)))
        self.assertEqual(met, refused, msg=str(vm.regions(compiled)))

    def test_every_member_that_a_value_read_stops_has_a_program(self):
        stopped = {
            line.split("\t")[2]
            for line in torch._rust._rules_dump().splitlines()
            if line.startswith("stop\ttorch\t")
            and ("depends on a value of a tensor" in line or "not witnessed" in line)
        }
        self.assertEqual(stopped, {member for member, _ in TORCH_READS.values()})

    @parametrize("name", list(TORCH_READS))
    @checks_isolated
    def test_a_member_that_reads_a_value_is_in_no_region(self, name):
        member, construct = TORCH_READS[name]
        table = {name: status for name, _, status in torch._rust._rules_torch()}
        self.assertEqual(table[member], "stop")
        compiled = self.calls(construct)
        # The call is a place of its own, which no trace is begun over.
        whys = [str(place.get("why")) for place in vm.regions(compiled)]
        self.assertTrue(
            any(f"{member} stops a trace" in why for why in whys), msg=str(whys)
        )
        met, refused = self.met_and_refused(compiled, member)
        self.assertEqual(met, refused, msg=str(vm.regions(compiled)))

    @parametrize("name", list(TORCH_READ_FORMS))
    @checks_isolated
    def test_a_form_that_reads_a_value_is_in_no_region(self, name):
        member, (form, construct), _ = TORCH_READ_FORMS[name]
