@instantiate_parametrized_tests
class TestVmBridge(TestCase):
    """No C++ exception leaves a function the executor calls across its
    bridge to torch: one that did would end the process. The functions are
    the ones recorded here, each with its kind; a function that joins the
    bridge and is not recorded fails, as does one whose kind is not what its
    declaration and its C++ body show."""

    hw_classification = HardwareClassification.GENERIC

    def bridge(self):
        if not os.path.isdir(CRATE):
            self.skipTest("the executor's source is not beside the tests")
        with open(os.path.join(CRATE, "bindings", "ffi.rs")) as f:
            text = re.sub(r"//[^\n]*", "", f.read())
        declared, rust_side = {}, []
        for way, block in re.findall(
            r'extern "(C\+\+|Rust)" \{(.*?)\n    \}', text, re.DOTALL
        ):
            for name, returns in re.findall(
                r"\bfn (\w+)\([^;]*?\)([^;]*);", block, re.DOTALL
            ):
                if way == "Rust":
                    rust_side.append(name)
                else:
                    declared[name] = "Result<" in returns
        return declared, sorted(rust_side)

    def body(self, name):
        """The C++ definition of the bridge's function ``name``."""
        csrc = os.path.join(os.path.dirname(CRATE), "csrc")
        found = []
        for source in BRIDGE_SOURCES:
            if not source.endswith(".cpp"):
                continue
            with open(os.path.join(csrc, source)) as f:
                text = f.read()
            head = rf"^(?!\s)[^\n;{{}}()]*\b{name}\([^;{{}}]*\)\s*(noexcept\s*)?\{{"
            for m in re.finditer(head, text, re.MULTILINE):
                found.append(
                    (
                        m.group(1) is not None,
                        text[m.end() : text.index("\n}\n", m.end())],
                    )
                )
        self.assertEqual(len(found), 1, msg=name)
        return found[0]

    def test_every_function_of_the_bridge_is_recorded(self):
        declared, rust_side = self.bridge()
        self.assertEqual(
            (
                sorted(set(declared) - set(BRIDGE_FUNCTIONS)),
                sorted(set(BRIDGE_FUNCTIONS) - set(declared)),
            ),
            ([], []),
            "functions of the bridge that are not recorded; recorded functions that are gone",
        )
        self.assertEqual(rust_side, BRIDGE_RUST_SIDE)

    def digest(self, name):
        text = " ".join(self.body(name)[1].split())
        return hashlib.sha256(text.encode()).hexdigest()[:12]

    def test_a_function_is_of_its_recorded_kind(self):
        declared, _ = self.bridge()
        for name, (kind, why, *read) in BRIDGE_FUNCTIONS.items():
            self.assertIn(kind, ("plain", "edge", "result"), msg=name)
            self.assertTrue(why, msg=name)
            self.assertEqual(declared[name], kind == "result", msg=name)
            noexcept, body = self.body(name)
            catches = re.search(r"\bedge(_py)?\(|catch \(\.\.\.\)", body) is not None
            self.assertEqual(catches, kind == "edge", msg=f"{name}: {kind}")
            if kind != "plain":
                self.assertEqual(noexcept, kind == "edge", msg=name)
            if kind == "plain":
                msg = f"the body of {name} is not the one that was read: read it again"
                self.assertEqual([self.digest(name)], read, msg=msg)
        for name, read in BRIDGE_HELPERS.items():
            msg = f"{name}, which plain functions call, is not as it was read"
            self.assertEqual(self.digest(name), read, msg=msg)

    def test_no_other_file_declares_cxx_and_c_is_declared_where_recorded(self):
        if not os.path.isdir(CRATE):
            self.skipTest("the executor's source is not beside the tests")
        cxx, c = [], []
        for path in sorted(
            glob.glob(os.path.join(CRATE, "**", "*.rs"), recursive=True)
        ):
            with open(path) as f:
                text = re.sub(r"//[^\n]*", "", f.read())
            if "cxx::bridge" in text or 'extern "C++"' in text:
                cxx.append(os.path.relpath(path, CRATE))
            if re.search(r'extern "C" \{', text):
                c.append(os.path.relpath(path, CRATE))
        self.assertEqual(cxx, ["bindings/ffi.rs"])
        self.assertEqual(c, BRIDGE_C_DECLARED_IN)
        csrc = os.path.join(os.path.dirname(CRATE), "csrc")
        sources = sorted(f for f in os.listdir(csrc) if not f.endswith(".h"))
        self.assertEqual(sources, BRIDGE_SOURCES)

    @parametrize("case", list(BRIDGE_ODD_TENSORS))
    @unittest.skipUnless(CHECKS_HAS_VM, "needs the torch._rust extension")
    @checks_isolated
    def test_a_tensor_whose_questions_raise_gets_the_refusing_answers(self, case):
        make, expected = BRIDGE_ODD_TENSORS[case]
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            odd = make()
        answers = torch._rust._bridge_answers(odd)
        # Every function of the bridge that takes a tensor was asked.
        asked = {n for n in BRIDGE_FUNCTIONS if n.startswith("tensor_")}
        self.assertEqual(
            set(answers) - {"a_pending_error_is_kept"}, asked - {"tensor_ident"}
        )
        self.assertTrue(answers["a_pending_error_is_kept"])
        for name, want in expected.items():
            self.assertEqual(answers[name], want, msg=f"{case}: {name}")
        # And a function on the VM that is handed it does what eager does.
        for body in (bridge_hands_on, bridge_computes_with):
            compiled = vm(body, passes=CHECKS_EARLY)
            for call in range(10):
                torch.manual_seed(call)
                x = torch.randn(4, 8)
                want = checks_outcome(body, x, odd)
                got = checks_outcome(compiled, x, odd)
                msg = f"{case}: {body.__name__}, call {call}"
                if isinstance(want, Exception):
                    self.assertIs(type(got), type(want), msg=msg)
                    continue
                self.assertEqual(got[0], want[0], atol=0, rtol=0, msg=msg)
                if isinstance(want[1], torch.Tensor) and want[1] is not odd:
                    self.assertEqual(got[1], want[1], atol=0, rtol=0, msg=msg)
                else:
                    self.assertIs(got[1], want[1], msg=msg)

    @unittest.skipUnless(CHECKS_HAS_VM, "needs the torch._rust extension")
    @checks_isolated
    def test_a_fallible_function_refuses(self):
        # Sizes that cannot be read as a list of ints: an error, where the
        # process ended.
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            nested = torch.nested.nested_tensor([torch.ones(2), torch.ones(3)])
        with self.assertRaisesRegex(RuntimeError, "sizes"):
            torch._rust.tensor_size(nested)
        self.assertEqual(torch._rust.tensor_size(torch.ones(2, 3)), [2, 3])


# The float32 precision family: every (backend, operator) pair of the new
# API and the legacy switches, which write pairs of it.
AMBIENT_FP32_BACKENDS = ("generic", "cuda", "mkldnn")
AMBIENT_FP32_OPS = ("all", "conv", "rnn", "matmul")
AMBIENT_FP32_PAIRS = [
    ("generic", "all"),
    *[(b, o) for b in ("cuda", "mkldnn") for o in AMBIENT_FP32_OPS],
]
AMBIENT_FP32_PRECISIONS = ("none", "ieee", "tf32", "bf16", "bfx9")


def ambient_fp32_pair_setter(backend, op):
    return lambda value: torch._C._set_fp32_precision_setter(backend, op, value)


# member -> (how it is set, every value it takes). A value torch refuses for
# a member (bf16 on cuda, bfx9 anywhere but cuda.matmul) raises there. The
# legacy switches by the functions torch.backends calls for them.
AMBIENT_FP32 = {
    **{
        f"{backend}.{op}.fp32_precision": (
            ambient_fp32_pair_setter(backend, op),
            AMBIENT_FP32_PRECISIONS,
        )
        for backend, op in AMBIENT_FP32_PAIRS
    },
    "set_float32_matmul_precision": (
        lambda value: torch.set_float32_matmul_precision(value),
        ("highest", "high", "medium"),
    ),
    "cuda.matmul.allow_tf32": (
        lambda value: torch._C._set_cublas_allow_tf32(value),
        (True, False),
    ),
    "cudnn.allow_tf32": (
        lambda value: torch._C._set_cudnn_allow_tf32(value),
        (False, True),
    ),
    "mkldnn.allow_tf32": (
        lambda value: torch._C._set_onednn_allow_tf32(value),
        (True, False),
    ),
}


def ambient_fp32_read():
    """Every answer of the family that a kernel reads, as Python reads it."""
    pairs = [torch._C._get_fp32_precision_getter(b, o) for b, o in AMBIENT_FP32_PAIRS]
    return (*pairs, torch._C._get_onednn_allow_tf32())


@contextlib.contextmanager
def ambient_fp32_left_as_found():
    """The family is put back as the test found it (a test may not leave it
    changed): the pairs others inherit from first, then what torch's own
    snapshot reads."""
    wide = [(b, o) for b, o in AMBIENT_FP32_PAIRS if o == "all"]
    found = [torch._C._get_fp32_precision_getter(b, o) for b, o in wide]
    snapshot = _snapshot_fp32_precision()
    try:
        yield
    finally:
        for (b, o), value in zip(wide, found):
            torch._C._set_fp32_precision_setter(b, o, value)
        _restore_fp32_precision(snapshot)


def ambient_fp32_pair_getter(backend, op):
    return lambda: torch._C._get_fp32_precision_getter(backend, op)


# What a program reads of the family: the pairs, and the legacy getters,
# which raise once the two APIs were mixed and which no kernel asks.
AMBIENT_FP32_LEGACY_GETTERS = (
    "get_float32_matmul_precision",
    "cuda.matmul.allow_tf32",
    "cudnn.allow_tf32",
)
AMBIENT_FP32_GETTERS = {
    **{f"{b}.{o}": ambient_fp32_pair_getter(b, o) for b, o in AMBIENT_FP32_PAIRS},
    "onednn_allow_tf32": lambda: torch._C._get_onednn_allow_tf32(),
    "get_float32_matmul_precision": lambda: torch.get_float32_matmul_precision(),
    "cuda.matmul.allow_tf32": lambda: torch.backends.cuda.matmul.allow_tf32,
    "cudnn.allow_tf32": lambda: torch.backends.cudnn.allow_tf32,
}

# Settings after which only a legacy getter answers otherwise: the pairs are
# as before the last one, the legacy matmul precision is not.
AMBIENT_FP32_LEGACY_ONLY = [
    ("cuda.matmul.fp32_precision", "tf32"),
    ("set_float32_matmul_precision", "medium"),
    ("mkldnn.matmul.fp32_precision", "none"),
    ("cuda.matmul.allow_tf32", True),
]


def ambient_fp32_legacy():
    """What the legacy getters answer, or that they raise."""
    asked = [AMBIENT_FP32_GETTERS[name] for name in AMBIENT_FP32_LEGACY_GETTERS]
    outcomes = [checks_outcome(get) for get in asked]
    return [type(o) if isinstance(o, Exception) else o for o in outcomes]


AMBIENT_FRESH_BODY = """
def {name}(x):
    y = x.sin() * 2 + torch.ones(8)
    {read}
    return (y @ y.t()).cos().tanh().exp(), k
"""


def ambient_fresh_body(name, read=None):
    """A function of its own code object (a region belongs to the code)."""
    scope = {"torch": torch, "read": read}
    text = AMBIENT_FRESH_BODY.format(name=name, read="k = read()" if read else "k = 0")
    exec(compile(text, f"<{name}>", "exec"), scope)
    return scope[name]


# How a function gets onto the VM and where a call of it is made from:
# entry(fn) gives (call, compiled). call(x, how) makes the call
# how(function, x) (a member of AMBIENT_NEUTRAL, ambient_called_under(...),
# or plainly) from where the entry says; `compiled` is what the regions of
# fn are counted on. Beside it in the table: whether the results are eager's
# to the bit.
def ambient_entered_directly(fn):
    compiled = vm(fn, passes=CHECKS_EARLY)
    return (lambda x, how=ambient_plainly: how(compiled, x)), compiled


def ambient_entered_on_another_thread(fn):
    compiled = vm(fn, passes=CHECKS_EARLY)
    calls = itertools.count()

    def call(x, how=ambient_plainly):
        # Every other call, the traced one among them, on a thread of its
        # own, which starts in the state a process starts in.
        if next(calls) % 2 == 0:
            return how(compiled, x)
        box = []
        made = threading.Thread(
            target=lambda: box.append(checks_outcome(how, compiled, x))
        )
        made.start()
        made.join()
        if isinstance(box[0], Exception):
            raise box[0]
        return box[0]

    return call, compiled


def ambient_entered_from_another_function(fn):
    compiled = vm(fn, passes=CHECKS_EARLY)

    # On the VM itself: the state changes, and the region is entered, inside
    # this function's run.
    def ambient_outer(x, how):
        return how(compiled, x)

    outer = vm(ambient_outer, passes=CHECKS_EARLY)
    return (lambda x, how=ambient_plainly: outer(x, how)), compiled


def ambient_entered_under_the_fast_list(fn):
    fast = vm.configure(vm.FAST, regions={"at": 3, "observe": 1}, pure_calls=1)
    compiled = vm(fn, passes=fast)
    return (lambda x, how=ambient_plainly: how(compiled, x)), compiled


AMBIENT_ENTRY = {
    "directly": (ambient_entered_directly, True),
    "on_another_thread": (ambient_entered_on_another_thread, True),
    "from_another_function": (ambient_entered_from_another_function, True),
    "under_the_fast_list": (ambient_entered_under_the_fast_list, False),
}
# (item of the word, entry) -> a defect of the engine that the pair meets,
# which is not the entry's: the test holds that it is still there.
AMBIENT_ENTRY_KNOWN = {
    ("default_dtype", "under_the_fast_list"): "a region that vm.FAST lowers "
    "while the default dtype is float64 hands out float32 on its first run",
}


def ambient_read_back():
    """The word as a program reads it back: the getters torch has for it."""
    return (
        torch.get_default_dtype(),
        torch.is_autocast_enabled("cpu"),
        torch.get_autocast_dtype("cpu"),
        torch.is_grad_enabled(),
        torch.is_inference_mode_enabled(),
        torch.are_deterministic_algorithms_enabled(),
        torch.is_deterministic_algorithms_warn_only_enabled(),
        torch._C._get_cudnn_enabled(),
        torch._C._get_cudnn_benchmark(),
        torch._C._get_cudnn_deterministic(),
        torch._C._get_mkldnn_enabled(),
        torch._C._is_view_replay_enabled(),
        torch._C._is_multithreading_enabled(),
    )


def ambient_body_reading_back(x):
    y = x.sin() * 2 + torch.ones(8)
    k = ambient_read_back()
    return (y @ y.t()).cos().tanh().exp(), k


def ambient_labelled_body(x):
    y = x.sin() * 2 + torch.ones(8)
    with torch.autograd.profiler.record_function("ambient_block"):
        z = (y @ y.t()).cos().tanh()
    return z.exp()


@instantiate_parametrized_tests
@unittest.skipUnless(CHECKS_HAS_VM, "needs the torch._rust extension and CPython 3.12")
class TestVmAmbientNeutral(TestCase):
    """Neutral is a positive statement: the state torch keeps for a thread
    is what a thread starts with, or what the ambient word holds. A thread
    as the process made it is neutral, every item of the word leaves it
    neutral and moves the word, and anything else is not neutral: the items
    somebody listed and a dispatch key nobody did."""

    hw_classification = HardwareClassification.GENERIC

    def test_a_thread_as_it_starts_is_neutral(self):
        import torch._dynamo
        import torch.func
        import torch.fx

        self.assertIsNone(torch._rust._not_neutral())
        asked = []
        made = threading.Thread(target=lambda: asked.append(torch._rust._not_neutral()))
        made.start()
        made.join()
        self.assertEqual(asked, [None])

    @parametrize("item", list(AMBIENT_WORD))
    def test_the_word_accounts_for(self, item):
        states = []
        for enter in AMBIENT_WORD[item]:
            with contextlib.ExitStack() if enter is None else enter():
                self.assertIsNone(torch._rust._not_neutral())
                states.append(torch._rust._ambient_word())
        self.assertIsNotNone(states[0])
        self.assertIsNotNone(states[1])
        self.assertNotEqual(states[0], states[1])
        self.assertIsNone(torch._rust._not_neutral())

    @parametrize("item", list(AMBIENT_NOT_NEUTRAL))
    def test_is_not_neutral(self, item):
        self.assertIsNone(torch._rust._not_neutral())
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            with AMBIENT_NOT_NEUTRAL[item]():
                self.assertIsNotNone(torch._rust._not_neutral())
        self.assertIsNone(torch._rust._not_neutral())

    def test_a_functorch_transform_is_not_neutral(self):
        asked = []

        def body(x):
            asked.append(torch._rust._not_neutral())
            return x.sum()

        torch.func.vmap(body)(torch.ones(2, 2))
        torch.func.grad(body)(torch.ones(2))
        torch.func.functionalize(body)(torch.ones(2))
        self.assertEqual(asked, ["a functorch transform is on"] * 3)
        self.assertIsNone(torch._rust._not_neutral())

    def test_the_tables_name_one_another(self):
        # What a call can be made under is asked without a call too.
        callable_under = set(AMBIENT_NEUTRAL) - {"a_functorch_transform"}
        self.assertEqual(callable_under - set(AMBIENT_NOT_NEUTRAL), set())

    @checks_isolated
    def test_a_profiler_records_the_calls_of_a_labelled_block(self):
        compiled = vm(ambient_labelled_body, passes=CHECKS_EARLY)
        ran = []
        for call in range(10):
            torch.manual_seed(call)
            x = torch.randn(4, 8, requires_grad=True)
            how = (
                ambient_under_the_autograd_profiler
                if call in (6, 7)
                else ambient_plainly
            )
            before = checks_region_runs(compiled, ambient_labelled_body)
            got, want = how(compiled, x), how(ambient_labelled_body, x)
            ran.append(checks_region_runs(compiled, ambient_labelled_body) - before)
            if call in (6, 7):
                self.assertIn(("ambient_block", 1), want[1])
                self.assertIn(("aten::matmul", 1), want[1])
                self.assertEqual(got[1], want[1], msg=f"call {call}")
                got, want = got[0], want[0]
            self.assertEqual(got, want, atol=0, rtol=0, msg=f"call {call}")
        self.assertGreaterEqual(ran[5], 1, msg=str(ran))
        self.assertEqual(ran[6:8], [0, 0], msg=str(ran))
        self.assertGreaterEqual(ran[9], 1, msg=str(ran))


@instantiate_parametrized_tests
@unittest.skipUnless(CHECKS_HAS_VM, "needs the torch._rust extension and CPython 3.12")
class TestVmAmbientEntry(TestCase):
    """A region runs from one place, which every entry passes: a block's
    region and a span's, on the thread of the trace and on another, from a
    call of the program and from inside another function's run on the VM,
    under the default list and under vm.FAST. There the thread must be
    neutral and its word the word of the region's trace, for every region:
    also with the check of the reads switched off, which used to take the
    comparison of the word with it."""

    hw_classification = HardwareClassification.GENERIC

    def agrees(self, got, want, msg, tolerance):
        if isinstance(want, torch.Tensor):
            self.assertIsInstance(got, torch.Tensor, msg=msg)
            self.assertEqual(got.dtype, want.dtype, msg=msg)
            self.assertEqual(got.requires_grad, want.requires_grad, msg=msg)
            self.assertEqual(got.is_inference(), want.is_inference(), msg=msg)
            if tolerance["rtol"] and want.dtype in (torch.bfloat16, torch.float16):
                # A lowering rounds a 16-bit result at other steps.
                tolerance = {"atol": 0.05, "rtol": 0.05}
            self.assertEqual(got, want, msg=msg, **tolerance)
        elif isinstance(want, tuple):
            self.assertEqual(len(got), len(want), msg=msg)
            for g, w in zip(got, want):
                self.agrees(g, w, msg, tolerance)
        else:
            self.assertEqual(got, want, msg=msg)

    def entered(self, entry, how, body=ambient_body):
        """Ten calls of ``body``, entered by ``entry``, call n made by
        ``how(n)``: how many of its regions each ran."""
        enter, exact = AMBIENT_ENTRY[entry]
        tolerance = {"atol": 0, "rtol": 0} if exact else {"atol": 1e-05, "rtol": 1e-04}
        call, compiled = enter(body)
        runs = []
        for n in range(10):
            torch.manual_seed(n)
            x = torch.randn(4, 8, requires_grad=True)
            before = checks_region_runs(compiled, body)
            got = call(x, how(n))
            runs.append(checks_region_runs(compiled, body) - before)
            self.agrees(got, how(n)(body, x), f"call {n}", tolerance)
        return runs

    def under_another_word(self, item, entry, body=ambient_body):
        first, other = AMBIENT_WORD[item]
        runs = self.entered(
            entry,
            lambda n: ambient_called_under(other if n in (6, 7) else first),
            body,
        )
        self.assertGreaterEqual(runs[5], 1, msg=str(runs))
        self.assertEqual(runs[6], 0, msg=str(runs))
        self.assertGreaterEqual(runs[9], 1, msg=str(runs))

    @parametrize("entry", list(AMBIENT_ENTRY))
    @parametrize("item", list(AMBIENT_WORD))
    @checks_isolated
    def test_a_call_under_another_word_enters_no_region(self, item, entry):
        known = AMBIENT_ENTRY_KNOWN.get((item, entry))
        if known is None:
            self.under_another_word(item, entry)
            return
        with self.assertRaises(AssertionError, msg=f"no longer so: {known}"):
            self.under_another_word(item, entry)

    @parametrize("item", list(AMBIENT_WORD))
    @checks_isolated
    def test_the_word_is_compared_with_the_reads_unchecked(self, item):
        # The body reads the word back: a region entered under another word
        # would hand out the answers of its trace.
        torch._rust._set_cfg_region_reads(False)
        try:
            self.under_another_word(item, "directly", ambient_body_reading_back)
        finally:
            torch._rust._set_cfg_region_reads(True)

    @parametrize("item", list(AMBIENT_WORD))
    @checks_isolated
    def test_a_word_changed_behind_the_checks_is_a_miss(self, item):
        # What a check of the entry releases can run a finalizer of the
        # program, which can change the thread's state: the door stands for
        # it. It opens on calls 6 and 7, behind the last check of the entry
        # that would take the call, and puts the thread under the other
        # state of the item until the call is over.
        first, other = AMBIENT_WORD[item]
        compiled = vm(ambient_body_reading_back, passes=CHECKS_EARLY)
        changed = contextlib.ExitStack()
        armed = []

        def door():
            if armed and other is not None:
                armed.clear()
                changed.enter_context(other())

        torch._rust._region_entry_door(door)
        runs = []
        try:
            with contextlib.ExitStack() if first is None else first():
                for n in range(10):
                    torch.manual_seed(n)
                    x = torch.randn(4, 8, requires_grad=True)
                    before = checks_region_runs(compiled, ambient_body_reading_back)
                    armed[:] = [True] if n in (6, 7) else []
                    with changed:
                        got = compiled(x)
                        entered = not armed
                        # Eager under the state the call ended in.
                        want = ambient_body_reading_back(x)
                    ran = checks_region_runs(compiled, ambient_body_reading_back)
                    runs.append(ran - before)
                    self.agrees(got, want, f"call {n}", {"atol": 0, "rtol": 0})
                    if n in (6, 7):
                        self.assertTrue(entered, msg=f"call {n}: the door did not open")
        finally:
            torch._rust._region_entry_door(None)
        # No region of the first state ran on the call the state changed in
        # (on the next one a region traced under the other state may run).
        self.assertGreaterEqual(runs[5], 1, msg=str(runs))
        self.assertEqual(runs[6], 0, msg=str(runs))
        self.assertGreaterEqual(runs[9], 1, msg=str(runs))

    @parametrize("entry", list(AMBIENT_ENTRY))
    @parametrize("item", list(AMBIENT_NEUTRAL))
    @checks_isolated
    def test_a_call_that_is_not_neutral_enters_no_region(self, item, entry):
        runs = self.entered(
            entry, lambda n: AMBIENT_NEUTRAL[item] if n in (6, 7) else ambient_plainly
        )
        self.assertGreaterEqual(runs[5], 1, msg=str(runs))
        self.assertEqual(runs[6:8], [0, 0], msg=str(runs))
        self.assertGreaterEqual(runs[9], 1, msg=str(runs))


@instantiate_parametrized_tests
@unittest.skipUnless(CHECKS_HAS_VM, "needs the torch._rust extension and CPython 3.12")
class TestVmAmbientFloat32(TestCase):
    """The float32 precision of every backend and operator is in the ambient
    word, as a kernel reads it: a region is for the precisions of its trace,
    whichever API set them and however the two were mixed, and no state of
    the family ends the process. The legacy getters, which raise in a mixed
    state, are not in the word: a body that asks one gets the answer of its
    own call."""

    hw_classification = HardwareClassification.GENERIC

    def settings(self):
        return [(m, v) for m, (_, values) in AMBIENT_FP32.items() for v in values]

    def put(self, member, value):
        """Whether torch took the value."""
        try:
            AMBIENT_FP32[member][0](value)
        except RuntimeError:
            return False
        return True

    def test_the_members_are_the_pairs_this_build_has(self):
        valid = []
        for backend, op in itertools.product(AMBIENT_FP32_BACKENDS, AMBIENT_FP32_OPS):
            try:
                torch._C._get_fp32_precision_getter(backend, op)
            except RuntimeError:
                continue
            valid.append((backend, op))
        self.assertEqual(sorted(valid), sorted(AMBIENT_FP32_PAIRS))

    @checks_isolated
    def test_the_word_follows_every_member_and_every_value(self):
        word = torch._rust._ambient_word
        took = set()
        with ambient_fp32_left_as_found():
            # Twice: every setting is made from more than one state.
            for member, value in self.settings() * 2:
                before, was = ambient_fp32_read(), word()
                if not self.put(member, value):
                    continue
                took.add(member)
                after, now = ambient_fp32_read(), word()
                msg = f"{member} = {value!r}: {before} -> {after}"
                self.assertIsNotNone(now, msg=msg)
                self.assertIsNone(torch._rust._not_neutral(), msg=msg)
                self.assertEqual(after != before, now != was, msg=msg)
        self.assertEqual(took, set(AMBIENT_FP32))

    @parametrize("entry", list(AMBIENT_ENTRY))
    @parametrize("member", list(AMBIENT_FP32))
    @checks_isolated
    def test_a_member_set_between_calls(self, member, entry):
        with ambient_fp32_left_as_found():
            for k, value in enumerate(AMBIENT_FP32[member][1]):
                self.set_between_calls(member, value, k, *AMBIENT_ENTRY[entry])

    def set_between_calls(self, member, value, k, enter, exact):
        tolerance = {"atol": 0, "rtol": 0} if exact else {"atol": 1e-05, "rtol": 1e-04}
        fn = ambient_fresh_body(f"ambient_fp32_{k}")
        call, compiled = enter(fn)
        runs, changed = [], None
        for n in range(10):
            if n == 6:
                before = ambient_fp32_read()
                if not self.put(member, value):
                    return
                changed = ambient_fp32_read() != before
            torch.manual_seed(n)
            x = torch.randn(4, 8, requires_grad=True)
            ran = checks_region_runs(compiled, fn)
            got = call(x)
            runs.append(checks_region_runs(compiled, fn) - ran)
            msg = f"{member} = {value!r}, call {n}"
            self.assertEqual(got[0], fn(x)[0], msg=msg, **tolerance)
        msg = f"{member} = {value!r}: {runs}"
        self.assertGreaterEqual(runs[5], 1, msg=msg)
        # The first call under other precisions is no region's; a call under
        # the same ones is.
        self.assertEqual(runs[6] == 0, changed, msg=msg)
        self.assertGreaterEqual(runs[9], 1, msg=msg)

    @parametrize("getter", list(AMBIENT_FP32_GETTERS))
    @checks_isolated
    def test_a_body_that_reads_the_family_gets_its_calls_answer(self, getter):
        read = AMBIENT_FP32_GETTERS[getter]
        fn = ambient_fresh_body("ambient_fp32_reads", read)
        compiled = vm(fn, passes=CHECKS_EARLY)

        def outcome(f, x):
            got = checks_outcome(f, x)
            return type(got) if isinstance(got, Exception) else got

        with ambient_fp32_left_as_found():
            ran, raised, unseen = self.reads_between_settings(fn, compiled, outcome)
        self.assertGreater(ran, 0)
        # The walk has settings the word does not see, which change what a
        # legacy getter answers.
        self.assertGreater(unseen, 0)
        if getter in ("get_float32_matmul_precision", "cuda.matmul.allow_tf32"):
            # And states in which the getter raises.
            self.assertGreater(raised, 0)

    def reads_between_settings(self, fn, compiled, outcome):
        ran = raised = unseen = 0
        settings = [*self.settings() * 2, *AMBIENT_FP32_LEGACY_ONLY]
        for step, (member, value) in enumerate(settings):
            before = (ambient_fp32_read(), ambient_fp32_legacy())
            self.put(member, value)
            after = (ambient_fp32_read(), ambient_fp32_legacy())
            unseen += after[0] == before[0] and after[1] != before[1]
            for again in range(3):
                torch.manual_seed(step)
                x = torch.randn(4, 8, requires_grad=True)
                runs = checks_region_runs(compiled, fn)
                got, want = outcome(compiled, x), outcome(fn, x)
                ran += checks_region_runs(compiled, fn) - runs
                msg = f"after {member} = {value!r}, call {again}"
                if isinstance(want, type):
                    raised += 1
                    self.assertIs(got, want, msg=msg)
                else:
                    self.assertEqual(got[1], want[1], msg=msg)
                    self.assertEqual(got[0], want[0], atol=0, rtol=0, msg=msg)
        return ran, raised, unseen


# A local that is bound and not read again, in front of a call that can
# raise: by name, what the report has to show. "region": a region of the
# function runs; "on CPython": the plan the optimizer makes of the function
# does not verify, so its frames run on CPython and a row says so; None:
# only that the function computes what eager does and that nothing is
# printed.
EDGE_DEAD_STORES = {
    "none_last": "on CPython",
    "const_int": "on CPython",
    "const_str": "on CPython",
    "const_bool": "on CPython",
    "const_tuple": "on CPython",
    "is_none": "on CPython",
    "built_tuple": "on CPython",
    "empty_dict": "on CPython",
    "empty_list": "on CPython",
    "a_lambda": "on CPython",
    "deleted": "region",
    "in_branch": "region",
    "in_loop": "region",
    "rebound_type": "on CPython",
    "cell": "on CPython",
    "in_try": "on CPython",
    "in_finally": "on CPython",
    "in_with_class": "on CPython",
    "in_with_generator": None,
    "cell_read": None,
    "raises_after": None,
}

EDGE_PLANS_PROGRAM = r"""
import contextlib, io, json, sys
import torch
from torch import vm

EARLY = vm.configure(vm.DEFAULT_PASSES, regions={"at": 3, "observe": 1}, pure_calls=1)


def work(x):
    return ((x.sin() * 2).cos() + 1).tanh().exp()


@contextlib.contextmanager
def managed():
    yield 2.0


class Managed:
    def __enter__(self):
        return 2.0

    def __exit__(self, *exc):
        return False


def none_last(x):
    y = work(x)
    t = y + 1
    t = None
    return work(y * 2.0)


def const_int(x):
    y = work(x)
    n = 3
    return work(y * 2.0)


def const_str(x):
    y = work(x)
    s = "name"
    return work(y * 2.0)


def const_bool(x):
    y = work(x)
    done = False
    return work(y * 2.0)


def const_tuple(x):
    y = work(x)
    pair = (1, 2)
    return work(y * 2.0)


def is_none(x):
    y = work(x)
    b = y is None
    return work(y * 2.0)


def built_tuple(x):
    y = work(x)
    pair = (y, x)
    return work(y * 2.0)


def empty_dict(x):
    y = work(x)
    d = {}
    return work(y * 2.0)


def empty_list(x):
    y = work(x)
    d = []
    return work(y * 2.0)


def a_lambda(x):
    y = work(x)
    f = lambda: 1
    return work(y * 2.0)


def deleted(x):
    y = work(x)
    t = y + 1
    del t
    return work(y * 2.0)


def in_branch(x):
    y = work(x)
    t = y + 1
    if x.shape[0] == 4:
        t = None
    return work(y * 2.0)


def in_loop(x):
    y = work(x)
    for i in range(2):
        t = y + i
        t = None
        y = work(y * 2.0)
    return y


def rebound_type(x):
    y = work(x)
    t = y + 1
    t = "text"
    t = 2.0
    return work(y * 2.0)


def cell(x):
    y = work(x)
    t = y + 1
    t = None

    def inner():
        return t

    return work(y * 2.0)


def in_try(x):
    y = work(x)
    try:
        t = y + 1
        t = None
        y = work(y * 2.0)
    except ValueError:
        y = y + 1
    return y


def in_finally(x):
    y = work(x)
    try:
        t = y + 1
    finally:
        t = None
    return work(y * 2.0)


def in_with_class(x):
    y = work(x)
    with Managed() as k:
        t = None
        y = work(y * k)
    return y


def in_with_generator(x):
    y = work(x)
    with managed() as k:
        t = None
        y = work(y * k)
    return y


def cell_read(x):
    y = work(x)
    t = None

    def inner():
        return t

    return work(y * 2.0), inner()


def raises_after(x):
    # The store is pending when the call raises: the handler reads the local.
    y = work(x)
    t = None
    try:
        y = work(y @ y)
    except RuntimeError:
        return work(y * 2.0), t
    return y


def callee(x):
    return work(x * 3.0) + 1


def caller(x):
    y = work(x)
    return callee(y * 2.0)


def same(a, b):
    if isinstance(a, torch.Tensor):
        return isinstance(b, torch.Tensor) and torch.equal(a, b)
    if isinstance(a, (tuple, list)):
        return len(a) == len(b) and all(same(p, q) for p, q in zip(a, b))
    return a == b


def run(fn, asked_until=None):
    compiled = vm(fn, passes=EARLY)
    err, verdicts = io.StringIO(), []
    with contextlib.redirect_stderr(err):
        for call in range(8):
            if call == asked_until:
                torch._rust._cfg_fail_plans(None)
            x = torch.full((4, 8), call + 1.0)
            try:
                got = compiled(x)
            except BaseException as e:
                got = f"raised {type(e).__name__}: {e}"
            verdicts.append("same" if same(got, fn(x)) else str(got)[:200])
    rows = [
        {"function": r["function"], "state": r["state"], "runs": r.get("runs") or 0, "why": r.get("why") or "", "kind": r["kind"]}
        for r in vm.regions(compiled)
    ]
    explained = [line.strip() for line in vm.explain(compiled).splitlines() if ": on CPython: " in line]
    return {"verdicts": verdicts, "printed": err.getvalue()[-1500:], "rows": rows, "explained": explained}


if sys.argv[1] == "family":
    print(json.dumps({name: run(globals()[name]) for name in json.loads(sys.argv[2])}))
elif sys.argv[1] == "first interrupted":
    # The first plan of `callee` meets a KeyboardInterrupt, in calls 0 and 1.
    torch._rust._cfg_fail_plans("callee", True, True)
    print(json.dumps(run(caller, 2)))
elif sys.argv[1] == "later interrupted":
    # Every later plan of `callee` meets a KeyboardInterrupt, in calls 0 and 1.
    torch._rust._cfg_fail_plans("callee", False, True)
    print(json.dumps(run(caller, 2)))
else:
    # No plan for `callee`: its first ("first") or every later one ("later").
    if sys.argv[1] != "none":
        torch._rust._cfg_fail_plans("callee", sys.argv[1] == "first")
    print(json.dumps(run(caller)))
"""


@unittest.skipUnless(
    CHECKS_HAS_VM, "torch.vm needs the Rust extension and CPython 3.12"
)
class TestVmEdgePlans(TestCase):
    """What the program sees where the executor cannot make a plan for a
    code: the code runs on CPython, as written, and ``torch.vm.regions`` and
    ``torch.vm.explain`` say why. Nothing is raised into the program and
    nothing is printed. The one family of programs known to meet it: a local
    that is bound and not read again, in front of a call, in the last block
    of a function (the plan the optimizer makes of it does not verify). An
    error that says nothing of the code (an interrupt) makes no row and
    leaves the code with the executor.
    """

    hw_classification = HardwareClassification.GENERIC

    def program(self, *args):
        command = [sys.executable, "-c", EDGE_PLANS_PROGRAM, *args]
        ran = subprocess.run(command, capture_output=True, text=True, timeout=900)
        self.assertEqual(ran.returncode, 0, ran.stderr[-2000:])
        return json.loads(ran.stdout.splitlines()[-1])

    def test_a_local_bound_and_not_read_again(self):
        found = self.program("family", json.dumps(list(EDGE_DEAD_STORES)))
        self.assertEqual(list(found), list(EDGE_DEAD_STORES))
        for name, want in EDGE_DEAD_STORES.items():
            got = found[name]
            self.assertEqual(got["verdicts"], ["same"] * 8, msg=name)
            self.assertNotIn("Error", got["printed"], msg=name)
            self.assertNotIn("Traceback", got["printed"], msg=name)
            own = [r for r in got["rows"] if r["function"] == name]
            left = [r for r in own if r["state"] == "on CPython"]
            ran = sum(r["runs"] for r in own if r["state"] == "region")
            if want == "on CPython":
                self.assertEqual(len(left), 1, msg=f"{name}: {own}")
                self.assertEqual(left[0]["kind"], "function", msg=name)
                self.assertIn("its code could not be planned again", left[0]["why"])
                self.assertIn("CFG verification failed", left[0]["why"])
                # No row says "region" of a region that never runs.
                self.assertEqual(ran, 0, msg=f"{name}: {own}")
                self.assertEqual(
                    [r for r in own if r["state"] == "region"], [], msg=name
                )
                continue
            self.assertEqual(left, [], msg=name)
            if want == "region":
                self.assertGreater(ran, 0, msg=f"{name}: {own}")

    def test_a_code_with_no_plan_runs_on_cpython_and_the_report_says_why(self):
        reasons = {
            "first": "no plan could be made for its code",
            "later": "its code could not be planned again",
        }
        for which, reason in reasons.items():
            got = self.program(which)
            self.assertEqual(got["verdicts"], ["same"] * 8, msg=which)
            self.assertEqual(got["printed"], "", msg=which)
            left = [r for r in got["rows"] if r["state"] == "on CPython"]
            self.assertEqual(len(left), 1, msg=f"{which}: {got['rows']}")
            self.assertEqual(
                (left[0]["function"], left[0]["kind"]), ("callee", "function")
            )
            self.assertIn(reason, left[0]["why"])
            self.assertIn("CFG verification failed", left[0]["why"])
            self.assertEqual(len(got["explained"]), 1, msg=which)
            self.assertIn(reason, got["explained"][0])
            # The frames it enters are the executor's again, and the code
            # around it keeps its regions.
            for function in ("work", "caller") if which == "first" else ("caller",):
                ran = sum(
                    r["runs"]
                    for r in got["rows"]
                    if r["function"] == function and r["state"] == "region"
                )
                self.assertGreater(ran, 0, msg=f"{which} {function}: {got['rows']}")
        got = self.program("none")
        self.assertEqual(got["verdicts"], ["same"] * 8)
        self.assertEqual([r for r in got["rows"] if r["state"] == "on CPython"], [])

    def test_an_interrupt_while_a_plan_is_made_is_no_row(self):
        # While the first plan of the callee is made: the interrupt is
        # raised into the program, as it was, and the code is planned at
        # its next call.
        got = self.program("first interrupted")
        for verdict in got["verdicts"][:2]:
            self.assertIn("raised KeyboardInterrupt", verdict)
        self.assertEqual(got["verdicts"][2:], ["same"] * 6)
        self.assertEqual([r for r in got["rows"] if r["state"] == "on CPython"], [])
        self.assertEqual(got["explained"], [])
        ran = sum(r["runs"] for r in got["rows"] if r["state"] == "region")
        self.assertGreater(ran, 0, msg=str(got["rows"]))
        # While a later plan is made, behind a frame of the code that
        # returned or in the round that plans every code again: the
        # interrupt is the program's too. The call raises it in place of
        # its result, nothing goes to sys.unraisablehook, and the code
        # stays the executor's.
        got = self.program("later interrupted")
        for verdict in got["verdicts"][:2]:
            self.assertIn("raised KeyboardInterrupt", verdict)
        self.assertEqual(got["verdicts"][2:], ["same"] * 6)
        self.assertNotIn("KeyboardInterrupt", got["printed"])
        self.assertEqual([r for r in got["rows"] if r["state"] == "on CPython"], [])
        ran = sum(
            r["runs"]
            for r in got["rows"]
            if r["function"] == "caller" and r["state"] == "region"
        )
        self.assertGreater(ran, 0, msg=str(got["rows"]))


# What sets a tool that is told of the frames CPython runs.
EDGE_TOOLS = ("setprofile", "settrace", "monitoring", "monitoring local", "cProfile")
# When it is set: around calls 0 and 1; around calls 6 and 7 (regions run
# before and after); by the body itself in calls 6 and 7, before its last
# call; on another thread, which makes calls 6 and 7.
EDGE_TOOL_WHEN = ("before", "between", "inside", "thread")

EDGE_TOOLS_PROGRAM = r"""
import cProfile, json, sys, threading
import torch
from torch import vm

EARLY = vm.configure(vm.DEFAULT_PASSES, regions={"at": 3, "observe": 1}, pure_calls=1)
tool, when = sys.argv[1], sys.argv[2]
ON = {"before": (0, 1), "between": (6, 7), "inside": (6, 7), "thread": (6, 7)}[when]
# Of what a tool is told, the part compared: the frames entered while it is
# set and the C calls they make. (A body that sets the tool itself is a
# frame in flight, and unsets it before it returns: see the test.) For the
# trace function a debugger puts on the frame in flight, that frame too.
WANTED = {"work", "sin", "cos", "tanh", "exp"} | (set() if when == "inside" and tool != "debugger" else {"body"})
STATE = {"inside": False}
MON = sys.monitoring
TOOL_ID = 3


def work(x):
    return ((x.sin() * 2).cos() + 1).tanh().exp()


class Tool:
    def __init__(self):
        self.seen = {}
        self.profile = None

    def count(self, kind, name):
        if name in WANTED:
            self.seen[f"{kind} {name}"] = self.seen.get(f"{kind} {name}", 0) + 1

    def profiled(self, frame, event, arg):
        self.count(event, getattr(arg, "__name__", "") if event.startswith("c_") else frame.f_code.co_name)

    def traced(self, frame, event, arg):
        self.count(event, frame.f_code.co_name)
        return self.traced

    def on(self):
        if tool == "setprofile":
            threading.setprofile(self.profiled) if when == "thread" else sys.setprofile(self.profiled)
        elif tool == "settrace":
            threading.settrace(self.traced) if when == "thread" else sys.settrace(self.traced)
        elif tool == "debugger":
            # What pdb.set_trace() and breakpoint() do: the frame in flight
            # (the caller's) gets the trace function, then sys.settrace.
            sys._getframe(1).f_trace = self.traced
            sys.settrace(self.traced)
        elif tool == "cProfile":
            self.profile = cProfile.Profile()
            self.profile.enable()
        else:
            MON.use_tool_id(TOOL_ID, "edge")
            MON.register_callback(TOOL_ID, MON.events.PY_START, lambda code, at: self.count("start", code.co_name))
            if tool == "monitoring":
                MON.register_callback(TOOL_ID, MON.events.PY_RETURN, lambda code, at, value: self.count("return", code.co_name))
                # A call is an event of the frame that makes it.
                called = lambda code, at, f, arg: code.co_name in WANTED and self.count("c_call", getattr(f, "__name__", ""))
                MON.register_callback(TOOL_ID, MON.events.CALL, called)
                MON.set_events(TOOL_ID, MON.events.PY_START | MON.events.PY_RETURN | MON.events.CALL)
            else:
                MON.set_local_events(TOOL_ID, work.__code__, MON.events.PY_START)

    def off(self):
        if tool == "setprofile":
            threading.setprofile(None) if when == "thread" else sys.setprofile(None)
        elif tool == "settrace":
            threading.settrace(None) if when == "thread" else sys.settrace(None)
        elif tool == "debugger":
            sys.settrace(None)
        elif tool == "cProfile":
            self.profile.disable()
            for entry in self.profile.getstats():
                name = entry.code if isinstance(entry.code, str) else entry.code.co_name
                for wanted in WANTED:
                    if name == wanted or (isinstance(entry.code, str) and f"'{wanted}'" in name):
                        self.seen[f"calls {wanted}"] = self.seen.get(f"calls {wanted}", 0) + entry.callcount
        else:
            if tool == "monitoring":
                MON.set_events(TOOL_ID, 0)
            else:
                MON.set_local_events(TOOL_ID, work.__code__, 0)
            MON.free_tool_id(TOOL_ID)


def body(x, t):
    y = work(x)
    if t is not None and when == "inside":
        t.on()
    z = work(y * 2.0)
    if t is not None and when == "inside":
        t.off()
    return z


def call(fn, x, on):
    # (the value, what the tool was told)
    t = Tool() if on else None
    if t is None or when == "inside":
        return fn(x, t), (t.seen if t else None)
    t.on()
    try:
        if when == "thread":
            out = []
            thread = threading.Thread(target=lambda: out.append(fn(x, t)))
            thread.start()
            thread.join()
            return out[0], t.seen
        return fn(x, t), t.seen
    finally:
        t.off()


def runs(compiled):
    return sum(r["runs"] for r in vm.regions(compiled) if r["state"] == "region")


compiled = vm(body, passes=EARLY)
rows = []
for i in range(12):
    x = torch.full((4, 8), i + 1.0)
    before = runs(compiled)
    got, told = call(compiled, x, i in ON)
    ran = runs(compiled) - before
    want, told_eager = call(body, x, i in ON)
    rows.append({"same": torch.equal(got, want), "told": told, "eager": told_eager, "ran": ran})
left = [r["why"] for r in vm.regions(compiled) if r["state"] == "on CPython"]
explained = [line.strip() for line in vm.explain(compiled).splitlines() if ": on CPython: " in line]
print(json.dumps({"rows": rows, "left": left, "explained": explained, "on": ON}))
"""


@unittest.skipUnless(
    CHECKS_HAS_VM, "torch.vm needs the Rust extension and CPython 3.12"
)
@instantiate_parametrized_tests
class TestVmEdgeTools(TestCase):
    """While a tool is set through ``sys.settrace``, ``sys.setprofile`` or
    ``sys.monitoring`` (a profiler, a debugger, a coverage tool), a frame
    that is entered runs on CPython, as written: the program computes what
    eager computes and raises nothing, the tool is told of the frame what it
    is told in eager, ``torch.vm.regions`` and ``torch.vm.explain`` say that
    frames ran on CPython for it, and regions run again once it is unset.
    A frame that is running on the executor when the tool is set (the body
    sets it itself) runs on to its end there: the tool is told of the frames
    it enters from then on, and nothing more of the frame itself.
    """

    hw_classification = HardwareClassification.GENERIC

    @parametrize("tool", EDGE_TOOLS)
    def test_a_tool_set(self, tool):
        def member(when):
            command = [sys.executable, "-c", EDGE_TOOLS_PROGRAM, tool, when]
            ran = subprocess.run(command, capture_output=True, text=True, timeout=600)
            return when, ran

        with concurrent.futures.ThreadPoolExecutor(len(EDGE_TOOL_WHEN)) as pool:
            members = list(pool.map(member, EDGE_TOOL_WHEN))
        self.assertEqual([when for when, _ in members], list(EDGE_TOOL_WHEN))
        for when, ran in members:
            self.assertEqual(ran.returncode, 0, msg=f"{when}: {ran.stderr[-2000:]}")
            found = json.loads(ran.stdout.splitlines()[-1])
            rows, on = found["rows"], found["on"]
            self.assertEqual([r["same"] for r in rows], [True] * 12, msg=when)
            for i in on:
                told, eager = rows[i]["told"], rows[i]["eager"]
                self.assertTrue(eager, msg=f"{when}: the tool was told nothing")
                if when == "inside" and i == on[0]:
                    # The first call that takes the body's new way: the
                    # frame in flight is the executor's, and what the
                    # executor does for it on that call (a trace of the new
                    # way) is told to the tool as well. Of the frames the
                    # body enters the tool is told all that eager tells.
                    more = {k: told.get(k, 0) - n for k, n in eager.items()}
                    self.assertGreaterEqual(
                        min(more.values()), 0, msg=f"{when}: {told}"
                    )
                else:
                    self.assertEqual(told, eager, msg=f"{when} call {i}")
                # No region runs for a frame the tool is to be told of.
                self.assertEqual(rows[i]["ran"], 0, msg=f"{when} call {i}")
            # Regions run again once the tool is unset.
            self.assertGreater(rows[-1]["ran"], 0, msg=when)
            if when != "before":
                self.assertGreater(rows[5]["ran"], 0, msg=when)
            self.assertEqual(len(found["left"]), 1, msg=when)
            self.assertIn("while a tool was set through sys.settrace", found["left"][0])
            self.assertEqual(len(found["explained"]), 1, msg=when)
            self.assertIn("every function", found["explained"][0])

    def test_a_trace_function_put_on_the_frame_in_flight(self):
        # A KNOWN DIFFERENCE, recorded: what pdb.set_trace() and breakpoint()
        # do in a function the body calls. They give the frame in flight a
        # trace function (f_trace) and then call sys.settrace: eager tells
        # that function the lines the frame in flight goes on to run. The
        # executor is running that frame and runs it on to its end, so
        # nothing more of it is told; the frames it enters from then on are
        # told as in eager. A correction changes what this test records.
        command = [sys.executable, "-c", EDGE_TOOLS_PROGRAM, "debugger", "inside"]
        ran = subprocess.run(command, capture_output=True, text=True, timeout=600)
        self.assertEqual(ran.returncode, 0, msg=ran.stderr[-2000:])
        found = json.loads(ran.stdout.splitlines()[-1])
        rows, (first, later) = found["rows"], found["on"]
        self.assertEqual([r["same"] for r in rows], [True] * 12)
        told, eager = rows[later]["told"], rows[later]["eager"]
        self.assertEqual(eager.get("line body"), 3, msg=str(eager))
        self.assertEqual(
            told, {k: n for k, n in eager.items() if k != "line body"}, msg=str(told)
        )
        # The first call that takes the body's new way: see test_a_tool_set.
        told, eager = rows[first]["told"], rows[first]["eager"]
        more = {k: told.get(k, 0) - n for k, n in eager.items()}
        self.assertGreaterEqual(min(more.values()), 0, msg=str(told))
        for i in (first, later):
            self.assertEqual(rows[i]["ran"], 0, msg=f"call {i}")
        self.assertGreater(rows[5]["ran"], 0)
        self.assertGreater(rows[-1]["ran"], 0)


# The calls of torch._C that tell of the dispatcher's thread-local state (or
# set it), by the start of their names, and the functorch getters of the
# same kind: what they return is no function of their operands.
EDGE_ASKER_PREFIXES = (
    "_dispatch_tls",
    "_dispatch_key",
    "_dispatch_has",
    "_dispatch_is",
)
EDGE_ASKER_NAMES = (
    "_dispatch_get_backend_keyset_from_autograd",
    "_dispatch_keys",
    "_dispatch_tls_is_dispatch_key_excluded",
    "_dispatch_tls_is_dispatch_key_included",
    "_dispatch_tls_local_exclude_set",
    "_dispatch_tls_local_include_set",
    "_dispatch_tls_set_dispatch_key_excluded",
    "_dispatch_tls_set_dispatch_key_included",
    "_dispatch_key_set",
)
EDGE_FUNCTORCH_PREFIXES = (
    "current_level",
    "get_",
    "peek_",
    "is_",
    "maybe_get_",
    "count_",
)

EDGE_ASKERS_PROGRAM = r"""
import json, sys
import torch
from torch import vm

C = torch._C
PD = C.DispatchKey.PreDispatch


def included(x):
    y = torch.relu(x)
    k = C._dispatch_tls_is_dispatch_key_included(PD)
    return y + 1, k


def excluded(x):
    y = torch.relu(x)
    k = C._dispatch_tls_is_dispatch_key_excluded(PD)
    return y + 1, k


def include_set(x):
    y = torch.relu(x)
    k = str(C._dispatch_tls_local_include_set())
    return y + 1, k


def exclude_set(x):
    y = torch.relu(x)
    k = str(C._dispatch_tls_local_exclude_set())
    return y + 1, k


def keys(x):
    y = torch.relu(x)
    k = str(C._dispatch_keys(y))
    return y + 1, k


def key_set(x):
    y = torch.relu(x)
    k = str(C._dispatch_key_set(y))
    return y + 1, k


body = globals()[sys.argv[1]]
xs = [torch.randn(8, 8) for _ in range(7)]
want = [body(x)[1] for x in xs]
passes = vm.configure(vm.DEFAULT_PASSES, regions={"at": 3, "observe": 1}, pure_calls=1)
compiled = vm(body, passes=passes)
got = [compiled(x)[1] for x in xs]
shadow = [s for s in torch._rust._calls_shadow() if s["place"].startswith(sys.argv[1] + ":")]
print(json.dumps({"same": [a == b for a, b in zip(want, got)], "shadow": shadow}))
"""


@unittest.skipUnless(
    CHECKS_HAS_VM, "torch.vm needs the Rust extension and CPython 3.12"
)
@instantiate_parametrized_tests
class TestVmEdgeAskers(TestCase):
    """A call that tells of the dispatcher's thread-local state reads what
    the engine itself put there for a recording (the PreDispatch key), so
    no list of calls may go on over one: none has a row in the rule table,
    and the recorder of call lists ends its recording in front of one, so
    that on a recorded run the call reads what eager reads.
    """

    hw_classification = HardwareClassification.GENERIC

    def test_no_asker_of_the_dispatch_state_has_a_row(self):
        askers = {
            f"torch._C.{n}"
            for n in dir(torch._C)
            if n.startswith(EDGE_ASKER_PREFIXES) or n in EDGE_ASKER_NAMES
        }
        askers |= {
            f"torch._C._functorch.{n}"
            for n in dir(torch._C._functorch)
            if n.startswith(EDGE_FUNCTORCH_PREFIXES)
        }
        # The walk found the family: the ones the finding names are there.
        named = {f"torch._C.{n}" for n in EDGE_ASKER_NAMES}
        self.assertEqual(named - askers, set())
        self.assertGreater(len(askers), 30)
        rows = [line.split("\t") for line in torch._rust._rules_dump().splitlines()]
        self.assertGreater(len([r for r in rows if r[:2] == ["row", "torch"]]), 100)
        # A member is named as it is found from torch (torch._C.NAME) or by
        # its own name (NAME, or MODULE.NAME).
        short = {a.rsplit(".", 1)[1] for a in askers}
        licensed = [
            r[:3]
            for r in rows
            if r[0] in ("row", "as")
            and (r[2] in askers or r[2].rsplit(".", 1)[-1] in short)
            and r[1] == "torch"
        ]
        self.assertEqual(licensed, [])

    @parametrize(
        "name",
        ["included", "excluded", "include_set", "exclude_set", "keys", "key_set"],
    )
    def test_a_recording_does_not_go_on_over_an_asker(self, name):
        env = {**os.environ, "TORCH_RUST_CALLS": "shadow"}
        command = [sys.executable, "-c", EDGE_ASKERS_PROGRAM, name]
        ran = subprocess.run(
            command, env=env, capture_output=True, text=True, timeout=600
        )
        self.assertEqual(ran.returncode, 0, ran.stderr[-2000:])
        found = json.loads(ran.stdout.splitlines()[-1])
        # The fourth call is the recorded run: the asker reads what eager
        # reads there, and on every call behind it.
        self.assertEqual(found["same"][3:], [True] * 4)
        self.assertTrue(found["shadow"])
        asker = {
            "included": "_dispatch_tls_is_dispatch_key_included",
            "excluded": "_dispatch_tls_is_dispatch_key_excluded",
            "include_set": "_dispatch_tls_local_include_set",
            "exclude_set": "_dispatch_tls_local_exclude_set",
            "keys": "_dispatch_keys",
            "key_set": "_dispatch_key_set",
        }[name]
        for record in found["shadow"]:
            # No list has the asker for an entry; a recording that met it
            # stopped there.
            self.assertNotIn(asker, record.get("text") or "", msg=str(record))
            if record["stop"] and asker in record["stop"][0]:
                self.assertEqual(record["status"], "stopped", msg=str(record))


# The release-order table (TestVmReleaseOrder): one member per kind of
# instruction that lets go of a reference. Under "== name": definitions, a
# line "--", and the statement (with no "--": the statement alone). The
# operands are objects whose death is logged: T(name) by its __del__, a
# tensor through F(tensor, name) by a weak reference's callback. From "row:"
# on the members hold the rows of the executor's order table against the
# interpreter: "row" and "instruction" a statement (or several) per
# instruction, "raise" an instruction that raises in C with operands under
# it, "unwind" what an exception pops, "two places" an operand that stands
# at two places of one instruction, "end" what a frame's end lets go of,
# "kept" an instruction that leaves an operand on the stack.
