class Q(T):
    @property
    def u(s):
        raise ValueError("u")


class Sq(collections.abc.Sequence):
    def __init__(s, *items):
        s.make = items

    def __len__(s):
        return len(s.make)

    def __getitem__(s, i):
        return s.make[i]()


class B0:
    m = 1

