# Calls that are no entry of the table's walk: the float's value while the
# region is traced, the body of `f(x, p)`, and how a region that ran holds
# the float ("input": of its graph, with no check; "value": it is checked on
# it; None: either). With "passed" the function is handed `(p, True)`.
FLOATS_PLAIN = {
    "dropout": (0.5, "y = x * 2\n    r = torch.dropout(y, p, True)", "value"),
    "dropout_starred_tuple": (
        0.5,
        "a = (x * 2, p, True)\n    r = torch.dropout(*a)",
        None,
    ),
    "dropout_starred_list": (
        0.5,
        "a = [x * 2, p, True]\n    r = torch.dropout(*a)",
        None,
    ),
    "dropout_starred_tail": (
        0.5,
        "y, a = x * 2, (p, True)\n    r = torch.dropout(y, *a)",
        None,
    ),
    "dropout_starred_passed": (
        0.5,
        "y = x * 2\n    r = torch.dropout(y, *p)",
        None,
    ),
    "dropout_functional": (
        0.5,
        "y = x * 2\n    r = F.dropout(y, p, True)",
        "value",
    ),
    "dropout_in_place": (
        0.5,
        "y = x * 2\n    r = torch.dropout_(y, p, True)",
        "value",
    ),
    "feature_dropout": (
        0.5,
        "y = x * 2\n    r = torch.feature_dropout(y, p, True)",
        "value",
    ),
    "cumulative_trapezoid": (
        0.0,
        "y = x * 2\n    r = torch.cumulative_trapezoid(y, dx=p)",
        "value",
    ),
    "where": (0.5, "y = x * 2\n    r = torch.where(y > 0, y.cos(), p)", "value"),
    "subtracted_from": (0.5, "y = x * 2\n    r = p - y.cos()", "value"),
    "divided": (0.5, "y = x * 2\n    r = p / (y.cos() + 2)", "value"),
    "leaky_relu_functional": (
        0.5,
        "y = x * 2\n    r = F.leaky_relu(y.cos(), p)",
        "value",
    ),
    "multiplied": (0.5, "y = x * 2\n    r = y.cos() * p", "input"),
    "clamped_by_keyword": (
        0.5,
        "y = x * 2\n    r = torch.clamp(y.cos(), min=p)",
        "input",
    ),
    "power": (0.5, "y = x * 2\n    r = (y.cos() + 2) ** p", "input"),
    "added_in_place": (0.5, "y = x * 2\n    r = y.cos().add_(p)", "input"),
    "filled": (0.5, "y = x * 2\n    r = y.cos() + torch.full((6,), p)", "input"),
}


def floats_handed_bytes(v):
    """What a comparison bit for bit takes of a result or an operand."""
    if isinstance(v, torch.Tensor):
        if v.is_quantized:
            return (str(v.dtype), tuple(v.shape), repr(v))
        return (str(v.dtype), tuple(v.shape), v.detach().numpy().tobytes())
    if isinstance(v, (tuple, list)):
        return (type(v).__name__, [floats_handed_bytes(i) for i in v])
    if isinstance(v, Exception):
        return (type(v).__name__, str(v)[:300])
    return (type(v).__name__, repr(v))


@instantiate_parametrized_tests
@unittest.skipUnless(CHECKS_HAS_VM, "needs the torch._rust extension and CPython 3.12")
class TestVmFloatsHanded(TestCase):
    """A float argument of a function that the function hands to a call of
    torch is, on every call, that call's own number. A region takes it as an
    input of its graph only where the trace of the call shows where the
    number went: the call traced one node, of the operator the callee is the
    binding of, with the float in the parameter it was handed at. Anywhere
    else the region is checked on the float's value: a callee that runs
    several operators hands them numbers of its own (dropout: 1 - p), and a
    call hands its keywords in its own order."""

    hw_classification = HardwareClassification.GENERIC

    @staticmethod
    def others(base):
        """Six other values for a float whose traced value is ``base``:
        other floats, the other zero, an int and a bool where they are
        equal to it, nan."""
        whole = base.is_integer()
        zero = -0.0 if (base == 0.0 and math.copysign(1.0, base) > 0) else 0.0
        return [
            base / 2 + 0.125,
            0.75 if base != 0.75 else 0.25,
            zero,
            int(base) if whole else 1,
            True if base == 1.0 else (1.0 if base != 1.0 else 2.0),
            float("nan"),
        ]

    def steps(self, base, pair=False):
        """The float (or the two) of each of 20 calls: ``base`` for the 8
        that trace the region, then other values, and back."""
        c = self.others(base)
        if not pair:
            order = [c[0]] * 3 + [base, c[1], c[2], base, c[3], base, c[4], base, c[5]]
            return [(k,) for k in [base] * 8 + order]
        same = (base, base)
        order = [(c[1], c[0]), (base, c[0]), same, (c[1], base), same, (c[0], c[0])]
        return [same] * 8 + [(c[0], c[1])] * 3 + [same, *order, same, (c[1], c[0])]

    def operand(self, how):
        if "l" in how:
            items = [self.operand(x) for x in how["l"]]
            return tuple(items) if how["tuple"] else items
        if "dtype" in how:
            return getattr(torch, how["dtype"])
        if "device" in how:
            return torch.device(how["device"])
        if "lit" in how:
            return ast.literal_eval(how["lit"])
        dtype, seeded = getattr(torch, how["t"]), torch.Generator().manual_seed(7)
        if dtype.is_floating_point:
            spread = torch.rand(how["s"], generator=seeded, dtype=torch.float64)
            made = (spread * (how["hi"] - how["lo"]) + how["lo"]).to(dtype)
        else:
            low, high = how["lo"], how["hi"] + 1
            made = torch.randint(low, high, how["s"], generator=seeded).to(dtype)
        return made.requires_grad_(True) if how.get("g") else made

    def beside_eager(self, source, operands, steps, grad=True):
        """The function ``f`` of ``source`` beside eager on 20 calls, the
        default generator seeded alike in front of both: the result, every
        operand after the call and where the generator is left are eager's,
        bit for bit. Returns the places of ``f``."""
        eager, traced = {"torch": torch, "F": F}, {"torch": torch, "F": F}
        exec(compile(source, "<a float handed over>", "exec"), eager)
        exec(compile(source, "<a float handed over>", "exec"), traced)
        compiled = vm(traced["f"], passes=CHECKS_EARLY)
        for call, floats in enumerate(steps):
            found = []
            for fn in (eager["f"], compiled):
                given = operands(call)
                torch.manual_seed(100 + call)
                with torch.set_grad_enabled(grad):
                    try:
                        out = fn(*given, *floats)
                    except Exception as e:
                        out = e
                left = torch.get_rng_state().numpy().tobytes()
                found.append((floats_handed_bytes([out, given]), left))
            # (Bit for bit, and not by the tolerances of assertEqual.)
            self.assertTrue(found[1] == found[0], msg=f"call {call} with {floats}")
        return [r for r in vm.regions(compiled) if r["function"] == "f"]

    def test_every_float_the_table_hands_over_has_a_program(self):
        # Of the table as it is: a place of a member with a float in its
        # measured domain, of a member that is no stop, has an entry or a
        # line that says why not; and no line is of a place that is gone.
        status = {name: said for name, _, said in torch._rust._rules_torch()}
        held = {(e["member"], place) for e in FLOATS_HANDED for place in e["places"]}
        places = set()
        for member, place, classes in torch._rust._rules_torch_domain():
            if status[member] != "stop" and any("float" in c for c in classes):
                places.add((member, place))
        self.assertEqual(sorted(places - held - set(FLOATS_NOT_HELD)), [])
        self.assertEqual(sorted(set(FLOATS_NOT_HELD) - places), [])
        self.assertEqual(sorted(held - places), [])
        self.assertGreaterEqual(len(held), 50)

    @parametrize("part", range(8))
    @checks_isolated
    def test_a_float_handed_to_a_member_is_the_calls_own(self, part):
        ran = 0
        for entry in FLOATS_HANDED[part::8]:
            floats = [f"k{i}" for i in range(len(entry["places"]))]
            head = ", ".join(["z", *entry["params"], *floats])
            source = (
                f"def f({head}):\n    u = (z * 2).cos()\n"
                f"    r = {entry['call']}\n    return r, (u + 1).tanh()\n"
            )

            def operands(call, entry=entry):
                z = torch.randn(4, 6, generator=torch.Generator().manual_seed(call))
                return [z, *map(self.operand, entry["operands"])]

            for base in entry["bases"]:
                with self.subTest(
                    member=entry["member"], call=entry["call"], base=base
                ):
                    steps = self.steps(ast.literal_eval(base), entry["kind"] == "pair")
                    rows = self.beside_eager(source, operands, steps, entry["grad"])
                    ran += any(r["state"] == "region" and r["runs"] for r in rows)
        # Regions ran over these calls: the comparisons are of regions.
        self.assertGreater(ran, 20)

    @parametrize("name", list(FLOATS_PLAIN))
    @checks_isolated
    def test_a_float_handed_to_a_call_of_torch(self, name):
        base, body, held = FLOATS_PLAIN[name]
        source = f"def f(x, p):\n    {body}\n    return r * 3 + 1\n"
        steps = self.steps(base)
        if name.endswith("_passed"):
            steps = [((k, True),) for (k,) in steps]

        def operands(call):
            return [torch.randn(4, 6, generator=torch.Generator().manual_seed(call))]

        rows = self.beside_eager(source, operands, steps)
        ran = [r for r in rows if r["state"] == "region" and r["runs"]]
        if held == "input":
            # One graph for every float: no value is checked.
            self.assertEqual([r["values"] for r in ran], [[]], msg=str(rows))
            self.assertGreaterEqual(ran[0]["runs"], 8, msg=str(rows))
        elif held == "value":
            self.assertGreaterEqual(len(ran), 1, msg=str(rows))
            for r in ran:
                self.assertIn(f"arg 1 (float) == {base!r}", r["values"], msg=str(r))

    def test_what_shows_where_a_float_of_a_call_went(self):
        import torch._rust_inductor as tracer

        class Named(float):
            pass

        aten, graph = torch.ops.aten, torch.fx.Graph()
        x, t = graph.placeholder("x"), torch.ones(2, 2)
        low, high = Named(0.5), Named(0.5)

        def node(op, *args, **kwargs):
            return graph.call_function(op, args, kwargs)

        # One node of the callee's own operator: each float goes to the
        # parameter it was handed at, in whatever order the call names them.
        clamped = [node(aten.clamp.default, x, 0.5, 0.5)]
        args, kwargs = tracer._handed_on(
            torch.clamp, clamped, (t,), {"max": high, "min": low}
        )
        self.assertIs(args[1], low)
        self.assertIs(args[2], high)
        self.assertEqual(kwargs, {})
        args, _ = tracer._handed_on(torch.Tensor.clamp, clamped, (t, low, high), {})
        self.assertIs(args[1], low)
        self.assertIs(args[2], high)
        args, _ = tracer._handed_on(aten.clamp.default, clamped, (t, low, high), {})
        self.assertIs(args[2], high)
        powered = [node(aten.pow.Tensor_Scalar, x, 0.5)]
        args, _ = tracer._handed_on(torch.Tensor.__pow__, powered, (t, low), {})
        self.assertIs(args[1], low)
        scaled = [node(aten.upsample_nearest2d.default, x, [4, 4], 0.5, 0.5)]
        upsample = torch._C._nn.upsample_nearest2d
        refused = {
            "a second node": (
                torch.clamp,
                [*clamped, node(aten.neg.default, x)],
                (t, low, high),
                {},
            ),
            "no node": (torch.clamp, [], (t, low, high), {}),
            "the node of another callee": (
                torch.dropout,
                [node(aten.div_.Scalar, x, 0.5)],
                (t, low, True),
                {},
            ),
            "a Python function": (
                F.hardtanh,
                [node(aten.hardtanh.default, x, 0.5, 0.5)],
                (t, low, high),
                {},
            ),
            "a keyword the operator has no parameter for": (
                torch.clamp,
                clamped,
                (),
                {"input": t, "min": low, "max": high},
            ),
            "a float the node has not": (
                torch.clamp,
                [node(aten.clamp.default, x, 0.5)],
                (t, low, high),
                {},
            ),
            "a float the call has not": (torch.clamp, clamped, (t, low), {}),
            "another float": (torch.clamp, clamped, (t, low, Named(0.25)), {}),
            "the other zero": (
                torch.clamp,
                [node(aten.clamp.default, x, 0.0)],
                (t, Named(-0.0)),
                {},
            ),
            "an operator with an overload that calls others": (
                upsample,
                scaled,
                (t, [4, 4], low, high),
                {},
            ),
            "a target that is no operator": (
                torch.clamp,
                [node(torch.clamp, x, 0.5, 0.5)],
                (t, low, high),
                {},
            ),
        }
        for why, (func, made, args, kwargs) in refused.items():
            with self.subTest(why=why):
                self.assertIsNone(tracer._handed_on(func, made, args, kwargs))
        self.assertTrue(tracer._decomposes(aten.upsample_nearest2d.default))
        self.assertTrue(tracer._decomposes(aten.where.self))
        self.assertFalse(tracer._decomposes(aten.clamp.default))
        self.assertFalse(tracer._decomposes(aten.mul.Tensor))


EFFECTS_RELEASES_PROGRAM = '''
import json
import sys
import weakref

import torch

vm = torch.vm
WITH = (*vm.DEFAULT_PASSES, vm.passes.Effects())
# (The default list, for the cells that say so: no write is a region's.)
PASSES = vm.DEFAULT_PASSES if sys.argv[3:] == ["default"] else WITH
UNRAISABLE = []
sys.unraisablehook = lambda u: UNRAISABLE.append(repr(u.exc_value)[:160])
CALLS = 40


def note(box):
    """What code of the program's that a death runs finds: how many modes
    are on, what the float attribute holds, and whether a tensor's value
    can be read."""
    try:
        value = float(box.buf.sum())
    except Exception as e:
        value = type(e).__name__
    c = torch._C
    modes = c._len_torch_dispatch_stack() + c._len_torch_function_stack()
    box.seen.append((modes, type(box.scale).__name__, value))


class Probe:
    """An object of the program's whose death runs code of the program's."""

    def __init__(self, box):
        self.box = box

    def __del__(self):
        note(self.box)


class Plain:
    pass


class Box(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.net = torch.nn.Linear(8, 8)
        self.register_buffer("buf", torch.zeros(4, 8))
        self.seen = []
        self.scale = 1.0
        self.a = None
        self.refs = []
        self.stop = False


def watched(o):
    if o.a is not None:
        o.refs.append(weakref.ref(o.a, lambda r, o=o: note(o)))


# How a traced call lets go of an object whose death runs code of the
# program's: what the caller puts there before each call, and the write of
# the compiled code that lets go of it.
RELEASES = {
    "attr": ("o.a = Probe(o)", "o.a = y"),
    "tensor_with_finalize": ("o.a is None or weakref.finalize(o.a, note, o)", "o.a = y"),
    "tensor_with_a_callback": ("watched(o)", "o.a = y"),
    "inside_a_list": ("o.a = [Probe(o)]", "o.a = y"),
    "inside_a_cell": ("o.a = (lambda p: lambda: p)(Probe(o))", "o.a = y"),
    "inside_an_object": ("o.a = Plain(); o.a.p = Probe(o)", "o.a = y"),
    "own_target": ("pass", "Probe(o).y = y"),
    "own_temporary": ("pass", "Probe(o)"),
}
BODY = """
def fill(o):
    {fill}

def fn(o, x, s):
    y = o.net(x).tanh().sin().cos().exp() * s
    o.scale = s * 2.0
    {write}
    return (y * 2).sin().cos().sum(0)
"""


def body(o, x, s):
    return o.net(x).tanh().sin().cos().exp() * s


def rows(g):
    shown = [r for r in vm.regions(g) if r["kind"] != "call"]
    return [(r["state"], r["runs"], str(r["why"])) for r in shown if r["state"] != "too small"]


def pair():
    torch.manual_seed(0)
    mine, theirs = Box(), Box()
    theirs.load_state_dict(mine.state_dict())
    return mine, theirs


def releases(name):
    fill, write = RELEASES[name]
    space = dict(globals())
    exec(BODY.format(fill=fill, write=write), space)
    fn, fill = space["fn"], space["fill"]
    mine, theirs = pair()
    g = vm(fn, passes=PASSES)
    same = []
    for call in range(CALLS):
        fill(mine)
        fill(theirs)
        x = torch.randn(4, 8)
        got, want = g(mine, x, 0.5 + call), fn(theirs, x, 0.5 + call)
        plain = type(mine.scale) is float and mine.scale == theirs.scale
        same.append(bool(torch.equal(got, want)) and plain)
        del got, want
    seen = {"seen": mine.seen, "eager": theirs.seen}
    return {"same": same, **seen, "rows": rows(g), "unraisable": UNRAISABLE}


# ---- An object held only through what the trace has parked: still a region --
class State:
    pass


def through_a_cell(o, x, s):
    # The write is to an object the call makes and lets go of. When the body
    # is over the object is held by a cell, and the cell by a read of the
    # trace alone: the write is none a region makes, and this is one region.
    st = State()
    st.h = body(o, x, s)

    def step(v):
        return v + st.h

    return step(x).sum(0)


def regions(name):
    fn = globals()[name]
    mine, theirs = pair()
    g = vm(fn, passes=WITH)
    same = []
    for call in range(CALLS):
        x = torch.randn(4, 8)
        got, want = g(mine, x, 2.0), fn(theirs, x, 2.0)
        same.append(bool(torch.equal(got, want)))
        del got, want
    return {"same": same, "rows": rows(g), "unraisable": UNRAISABLE}


# ---- Code that a death runs at a trace's gate calls a compiled function ------
X0 = torch.ones(4, 8)
BAD = torch.zeros(3, 3)
CURRENT = [None]


def clean_region(x):
    # Only computes: a region where it is traced.
    return x.tanh().sin().cos().exp().sum()


def clean_given_up(x):
    # Raises under a trace as it does without one, and goes on.
    try:
        return (x.tanh().sin().cos().exp() @ BAD).sum()
    except RuntimeError:
        return 0.0


def clean_not_yet(x):
    # Runs a line on some calls that the calls before did not run.
    y = x.tanh().sin().cos().exp()
    if len(CURRENT[0].seen) % 7 == 3:
        y = y.neg().abs()
    return y.sum()


def clean_raises(x):
    y = x.tanh().sin().cos().exp()
    raise ValueError(float(y.sum()))


class Dying:
    k = 2

    def __del__(self):
        o = CURRENT[0]
        o.seen.append("died")
        try:
            o.clean(X0)
        except ValueError:
            o.seen.append("raised")


# How the block comes to hold the object until its trace is over: by a
# read of its class's attribute, or by a write to it.
NESTED = {"default": "z = Dying().k", "effects": "Dying().y = y; z = 2"}
NESTED_BODY = """
def fn(o, x):
    y = o.net(x).tanh().sin().cos().exp()
    {held}
    return (y * z).sin().cos().sum(0)
"""


def nested(name):
    # The object dies at the gate of the block's trace, and its __del__
    # calls a function torch.vm compiled: once per call, as on eager.
    space = dict(globals())
    exec(NESTED_BODY.format(held=NESTED[sys.argv[3]]), space)
    fn, clean = space["fn"], globals()["clean_" + name]
    mine, theirs = pair()
    mine.clean, theirs.clean = vm(clean, passes=PASSES), clean
    g = vm(fn, passes=PASSES)
    same = []
    for call in range(CALLS):
        x = torch.randn(4, 8)
        CURRENT[0] = mine
        got = g(mine, x)
        CURRENT[0] = theirs
        want = fn(theirs, x)
        same.append(bool(torch.equal(got, want)) and mine.seen == theirs.seen)
        del got, want
    mine_rows = [r for r in vm.regions(g) if r["kind"] != "call" and r["function"] == "fn"]
    found = [(r["state"], r["runs"], str(r["why"])) for r in mine_rows if r["state"] != "too small"]
    seen = {"seen": mine.seen, "eager": theirs.seen}
    return {"same": same, **seen, "rows": found, "unraisable": UNRAISABLE}


# ---- A trace that is given up behind a write --------------------------------
class Stop(Exception):
    pass


def halt(o):
    if o.stop:
        raise Stop


def given_up(o, x, s):
    y = body(o, x, s)
    o.scale = s * 2.0
    o.a = y
    halt(o)
    return (y * 2).sin().cos().sum(0)


def given_up_with_a_list(o, x, s, acc):
    y = body(o, x, s)
    o.scale = s * 2.0
    o.a = y
    acc.append(1)
    halt(o)
    return (y * 2).sin().cos().sum(0)


def undo(name):
    # From call 20 on the code raises behind its writes, on eager and on the
    # traced call alike: the trace is given up, what it wrote is taken back
    # and the code runs again as written.
    fn = globals()[name]
    mine, theirs = pair()
    g = vm(fn, passes=WITH)
    same, lists = [], ([], [])
    for call in range(CALLS):
        x = torch.randn(4, 8)
        out = []
        for o, f, acc in ((mine, g, lists[0]), (theirs, fn, lists[1])):
            o.a = Probe(o)
            o.stop = call >= 20
            extra = (acc,) if name == "given_up_with_a_list" else ()
            try:
                out.append(f(o, x, 0.5 + call, *extra))
            except Stop:
                out.append(None)
        if out[0] is None or out[1] is None:
            value = out[0] is None and out[1] is None
        else:
            value = bool(torch.equal(*out))
        plain = type(mine.scale) is float and mine.scale == theirs.scale
        state = plain and lists[0] == lists[1] and bool(torch.equal(mine.a, theirs.a))
        same.append(value and state)
        del out
    seen = {"seen": mine.seen, "eager": theirs.seen}
    return {"same": same, **seen, "rows": rows(g), "unraisable": UNRAISABLE}


# ---- A trace whose own code fails behind the body ---------------------------
def fails_behind(name):
    import torch._rust_inductor  # noqa: F401
    import torch.vm._writes as writes

    rust = torch._rust
    mine, theirs = pair()

    def fn(o, x, s):
        y = body(o, x, s)
        o.scale = s * 2.0
        o.buf.add_(1)
        o.a = y
        return (y * 2).sin().cos().sum(0)

    failed = []

    def fail():
        failed.append(1)
        raise RuntimeError("the tracer's own code fails behind the body")

    if name == "settled":
        rust._region_settled = lambda *a: fail()
    elif name == "plan":
        writes.Written.plan = lambda self, *a: fail()
    else:
        real = writes._put_plain

        def failing(how, target, values, plain):
            if how.__name__ == "__setattr__" and values[0] == "scale" and not failed:
                fail()
            return real(how, target, values, plain)

        writes._put_plain = failing
    g = vm(fn, passes=WITH)
    same, kinds, raised = [], [], []
    for call in range(CALLS):
        x = torch.randn(4, 8)
        want = fn(theirs, x, 0.5 + call)
        try:
            got = g(mine, x, 0.5 + call)
        except RuntimeError as e:
            # The engine's own error: the state is compared all the same.
            raised.append((call, str(e)[:60], type(e.__cause__).__name__))
            got = want
        state = mine.scale == theirs.scale and bool(torch.equal(mine.buf, theirs.buf))
        same.append(bool(torch.equal(got, want)) and state and bool(torch.equal(mine.a, theirs.a)))
        kinds.append(type(mine.scale).__name__)
        del got, want
    found = {"same": same, "kinds": kinds, "failed": len(failed), "raised": raised}
    return {**found, "rows": rows(g), "unraisable": UNRAISABLE}


if __name__ == "__main__":
    kinds = {"releases": releases, "regions": regions, "undo": undo, "fails": fails_behind}
    kinds["nested"] = nested
    print(json.dumps(kinds[sys.argv[1]](sys.argv[2])))
'''

EFFECTS_RELEASES = [
    "attr",
    "tensor_with_finalize",
    "tensor_with_a_callback",
    "inside_a_list",
    "inside_a_cell",
    "inside_an_object",
    "own_target",
]


@unittest.skipUnless(
    CHECKS_HAS_VM, "torch.vm needs the Rust extension and CPython 3.12"
)
@instantiate_parametrized_tests
class TestVmEffectsReleases(TestCase):
    """With the Effects pass a traced call keeps what its stores replaced,
    the writes nothing can see and what it read from its own temporaries
    until its trace is over. It lets go of none of that while the tracer's
    dispatch modes are on or its stand-ins for floats sit in the program's
    objects: code that the death of such an object runs (a ``__del__``,
    ``weakref.finalize``, the callback of a weak reference; the object held
    directly, or through a list, a cell or another object) runs once per
    call, as on eager, with no mode on, a float where the program stored
    one and tensors whose values can be read. The trace it ran under is no
    region. A trace that is given up behind a write leaves what eager
    leaves, and so does one whose own code fails behind the body: no
    stand-in of the tracer's stays in the program's state, or the call
    raises. Such code may call a function torch.vm compiled: no trace
    begins while a trace is being closed, the function runs as written.
    (What such code sees of the state is that of the end of the traced
    code, not of the store: a limit of the pass, which its docstring
    states.)"""

    hw_classification = HardwareClassification.GENERIC

    def walk(self, kind, name, *more):
        command = [sys.executable, "-c", EFFECTS_RELEASES_PROGRAM, kind, name, *more]
        ran = subprocess.run(command, capture_output=True, text=True, timeout=1200)
        self.assertEqual(ran.returncode, 0, ran.stderr[-3000:])
        found = json.loads(ran.stdout.splitlines()[-1])
        self.assertEqual(found["unraisable"], [])
        self.assertTrue(all(found["same"]), msg=str(found["same"]))
        return found

    def plain(self, found):
        self.assertEqual(len(found["seen"]), len(found["eager"]))
        for modes, kind, value in found["seen"]:
            state = (modes, kind, type(value))
            self.assertEqual(state, (0, "float", float), msg=str(found["seen"]))

    @parametrize("name", EFFECTS_RELEASES)
    def test_code_a_death_runs_finds_the_state_of_the_program(self, name):
        found = self.walk("releases", name)
        self.plain(found)
        # The death was of something the trace itself let go of, and the
        # trace is no region for it.
        refused = [why for state, _, why in found["rows"] if state == "refused"]
        self.assertEqual(len(refused), 1, msg=str(found["rows"]))
        self.assertIn("a frame that is not the body's ran under it", refused[0])
        self.assertIn("when the trace let go of what it held", refused[0])

    def test_an_object_a_call_makes_and_drops_dies_in_the_state_of_the_program(self):
        # Under the default list too: the object is held by the trace's
        # record of the store its __init__ made, until the trace is over.
        found = self.walk("releases", "own_temporary", "default")
        self.plain(found)
        refused = [why for state, _, why in found["rows"] if state == "refused"]
        self.assertEqual(len(refused), 1, msg=str(found["rows"]))
        self.assertIn("when the trace let go of what it held", refused[0])

    @parametrize("clean", ["region", "given_up", "not_yet", "raises"])
    @parametrize("passes", ["default", "effects"])
    def test_code_a_death_runs_at_the_gate_begins_no_trace(self, clean, passes):
        # The __del__ calls a compiled function. A trace begun there would
        # reset what the trace being closed has found (the frame of the
        # __del__ itself), and that trace would be handed over as a region
        # that leaves the object and its __del__ out.
        found = self.walk("nested", clean, passes)
        self.assertEqual(found["seen"], found["eager"])
        self.assertEqual(found["seen"].count("died"), 40)
        states = [state for state, _, _ in found["rows"]]
        self.assertNotIn("region", states, msg=str(found["rows"]))
        refused = [why for state, _, why in found["rows"] if state == "refused"]
        self.assertEqual(len(refused), 1, msg=str(found["rows"]))
        # (For the __del__ itself, not for a frame of the engine's own
        # that a trace begun inside it would leave behind.)
        self.assertIn("a frame that is not the body's ran under it", refused[0])
        self.assertIn("Dying.__del__", refused[0])

    def test_a_write_to_what_the_trace_alone_holds_is_none_of_a_region(self):
        found = self.walk("regions", "through_a_cell")
        self.assertEqual([state for state, _, _ in found["rows"]], ["region"])
        self.assertGreater(found["rows"][0][1], 0)

    @parametrize("name", ["given_up", "given_up_with_a_list"])
    def test_a_trace_given_up_behind_a_write_leaves_what_eager_leaves(self, name):
        found = self.walk("undo", name)
        self.plain(found)
        self.assertIn("gave up", [state for state, _, _ in found["rows"]])

    @parametrize("name", ["settled", "plan"])
    def test_a_trace_that_fails_behind_its_body_leaves_no_stand_in(self, name):
        found = self.walk("fails", name)
        self.assertGreater(found["failed"], 0)
        self.assertEqual(set(found["kinds"]), {"float"})
        self.assertEqual(found["raised"], [])

    def test_a_stand_in_that_cannot_be_replaced_is_an_error(self):
        found = self.walk("fails", "put")
        self.assertEqual(found["failed"], 1)
        self.assertEqual(len(found["raised"]), 1, msg=str(found))
        call, text, cause = found["raised"][0]
        self.assertIn("torch.vm: a traced call stored a float", text)
        self.assertEqual(cause, "RuntimeError")
        # The one call that raised left the stand-in; the store of the next
        # call, which runs as written, puts a float.
        stand_ins = [i for i, k in enumerate(found["kinds"]) if k != "float"]
        self.assertEqual(stand_ins, [call])


if __name__ == "__main__":
    run_tests()
